registrarDetalhes({"PT-001":{"cognitivo":{"motivo":"Cobrar o uso do relativo 'cujo', que exige relação de posse entre antecedente e consequente.","palavraCritica":"cujos"},"comentario":{"resolucao":"ERRADO. 'Os quais' retoma 'os índices de criminalidade' como sujeito de 'dependem'. 'Cujo' expressa posse e deve anteceder substantivo ('cujos índices'), o que tornaria o período agramatical: 'a redução dos índices..., cujos dependem...' não tem estrutura possível.","fundamento":"Gramática normativa — emprego dos pronomes relativos.","macete":"CUJO = 'de quem/de que' + coisa possuída, sem artigo depois.","erroComum":"Aceitar 'cujo' como sinônimo culto de 'o qual'.","comoBancaPensa":"Reescritura é o formato nº 1 de Português no CEBRASPE: julgue sempre SINTAXE + SENTIDO."}},"PT-002":{"cognitivo":{"motivo":"Diferença entre conectivo adversativo coordenativo e conjunção concessiva subordinativa.","palavraCritica":"Conquanto (= embora)"},"comentario":{"resolucao":"ERRADO. 'No entanto' é conectivo adversativo que liga períodos independentes. 'Conquanto' é conjunção subordinativa concessiva (equivale a 'embora') e exigiria reestruturação do período (verbo no subjuntivo e oração principal), o que não ocorre na simples substituição.","fundamento":"Gramática normativa — coordenação e subordinação.","macete":"Troca segura: no entanto ↔ porém ↔ contudo ↔ entretanto ↔ todavia.","erroComum":"Aceitar troca entre conectivo de grupo diferente por proximidade de sentido.","comoBancaPensa":"É a segunda cobrança favorita em Português: substituição de conectivo com mudança de classe gramatical."}},"PT-003":{"cognitivo":{"motivo":"Combinar classificação correta (aposto) com consequência falsa (supressão possível).","palavraCritica":"manteria a correção"},"comentario":{"resolucao":"ERRADO. O trecho é, de fato, aposto explicativo referido a 'A segurança pública' — mas exatamente por isso as vírgulas duplas são obrigatórias na intercalação. A supressão fundiria aposto e sujeito sem sinalização, comprometendo a correção gramatical.","fundamento":"Gramática normativa — pontuação do aposto (estrutura análoga à do art. 144, caput, da CF).","macete":"Explicação intercalada = 'entre parênteses' = vírgulas obrigatórias dos dois lados.","erroComum":"Validar o item pela metade verdadeira.","comoBancaPensa":"Verdade + falso emendado: o acerto parcial compra a confiança do candidato."}},"PT-004":{"cognitivo":{"motivo":"Cobrar a justificativa da crase (regência + artigo), formato típico da banca.","palavraCritica":"termo regente"},"comentario":{"resolucao":"CERTO. 'Acesso' rege a preposição 'a' e 'informação' admite o artigo 'a' → crase. 'Essencial' rege 'a' e 'consolidação' admite 'a' → crase. A justificativa sintática (preposição + artigo) é a mesma nos dois casos.","fundamento":"Gramática normativa — regência e crase.","macete":"Troque pelo masculino: apareceu 'AO', crase confirmada.","erroComum":"Buscar diferenças de regência inexistentes por desconfiança excessiva.","comoBancaPensa":"Também cobra itens CERTOS de crase — julgue pela regra, não pelo medo."}},"PT-005":{"cognitivo":{"motivo":"Cobrar a impessoalidade do verbo 'fazer' indicando tempo decorrido.","palavraCritica":"Fazem (deveria ser 'Faz')"},"comentario":{"resolucao":"ERRADO. O verbo 'fazer' indicando tempo decorrido é impessoal (sem sujeito) e permanece invariável na 3ª pessoa do singular: 'Faz cinco anos'. 'Cinco anos' é objeto, não sujeito. A verbalização no plural viola a norma-padrão.","fundamento":"Gramática normativa — verbos impessoais (fazer/haver de tempo).","macete":"Troque 'fazer' por 'haver': 'Há cinco anos' (nunca 'Hão cinco anos'). Se cabe 'há', fica singular.","erroComum":"Flexionar 'fazer'/'haver' de tempo como se 'anos' fosse sujeito.","comoBancaPensa":"Verbo impessoal com expressão de tempo no plural é isca clássica de concordância."}},"PT-006":{"cognitivo":{"motivo":"Cobrar a regra da crase facultativa/vedada em 'a distância' × 'à distância de'.","palavraCritica":"a distância × à distância de"},"comentario":{"resolucao":"CERTO. Segundo a norma-padrão, não se emprega crase em 'a distância' quando a expressão não está determinada por adjunto especificador. A crase seria obrigatória em 'à distância de cinquenta metros'. Portanto, a ausência de acento está correta.","fundamento":"Gramática normativa — crase em locuções adverbiais.","macete":"'Ficar a distância' = sem crase; 'ficar à distância de X' = com crase.","erroComum":"Acentuar por reflexo, só porque 'distância' é feminino.","comoBancaPensa":"Crase em expressões 'a distância', 'a olho nu', 'a bordo' é campo minado da banca."}},"PT-007":{"cognitivo":{"motivo":"Cobrar as palavras atrativas que exigem próclise.","palavraCritica":"nunca / se viu"},"comentario":{"resolucao":"CERTO. Advérbios de negação como 'nunca' são palavras atrativas que impõem a próclise: 'Nunca se viu'. A ênclise ('viu-se') seria incorreta nesse contexto.","fundamento":"Gramática normativa — colocação pronominal (fatores de próclise).","macete":"Tem palavra 'negativa/atrativa' antes do verbo? Pronome cola ANTES (próclise).","erroComum":"Usar ênclise após negação, advérbio ou pronome relativo.","comoBancaPensa":"Colocação pronominal é cobrada por meio de reescrita — atenção ao gatilho atrativo."}},"PT-008":{"cognitivo":{"motivo":"Cobrar a dupla regência do verbo 'assistir' conforme o sentido.","palavraCritica":"assistir a (presenciar) × assistir (ajudar)"},"comentario":{"resolucao":"ERRADO. No sentido de presenciar/ver, 'assistir' é transitivo indireto e exige a preposição 'a': 'assistiram AO laudo'. Como transitivo direto, 'assistir' significa prestar assistência ('assistir o doente'). A frase inverteu a regência.","fundamento":"Gramática normativa — regência do verbo 'assistir'.","macete":"Ver = assistir A. Ajudar = assistir (sem preposição). Cabe também 'assistir a' no sentido de caber direito (assiste-lhe o direito).","erroComum":"Usar 'assistir' (presenciar) sem a preposição 'a'.","comoBancaPensa":"Verbos de dupla regência (assistir, visar, aspirar, proceder) são pratos cheios para C/E."}},"PT-009":{"cognitivo":{"motivo":"Cobrar a conversão ativa→passiva analítica, tema recorrente de reescritura.","palavraCritica":"objeto vira sujeito; sujeito vira agente da passiva"},"comentario":{"resolucao":"CERTO. Na voz passiva analítica, o objeto direto ('o inquérito') torna-se sujeito, o verbo assume a forma 'ser + particípio' no mesmo tempo ('foi instaurado') e o sujeito original vira agente da passiva ('pela autoridade policial'). O sentido é preservado.","fundamento":"Gramática normativa — vozes verbais.","macete":"Quem sofre a ação vira sujeito; quem pratica vira 'agente da passiva' (introduzido por 'por').","erroComum":"Mudar o tempo verbal ou trocar o agente na conversão.","comoBancaPensa":"Conversão de voz é reescritura clássica: julgue tempo verbal + agente."}},"PT-010":{"cognitivo":{"motivo":"Cobrar a vedação da vírgula entre sujeito e verbo.","palavraCritica":"vírgula separando sujeito e verbo (proibida)"},"comentario":{"resolucao":"ERRADO. A norma-padrão veda a vírgula única entre o sujeito ('Os agentes responsáveis pela investigação') e o verbo ('apresentaram'). A pontuação só seria admissível para isolar um termo intercalado, delimitado por um PAR de vírgulas.","fundamento":"Gramática normativa — pontuação (sujeito × predicado).","macete":"Uma vírgula sozinha entre sujeito e verbo = erro. Só vale par de vírgulas isolando intercalado.","erroComum":"Isolar o sujeito com uma única vírgula.","comoBancaPensa":"Reescritura de pontuação testa a proibição sujeito-verbo."}},"PT-011":{"cognitivo":{"motivo":"Cobrar a noção de paralelismo sintático.","palavraCritica":"coordenar termos de mesma função/estrutura"},"comentario":{"resolucao":"CERTO. Há quebra de paralelismo ao coordenar um substantivo ('cautela') com uma oração ('que os agentes agissem com discrição'). A correção iguala as estruturas: dois substantivos coordenados ('cautela e discrição') ou duas orações.","fundamento":"Gramática normativa — paralelismo sintático.","macete":"Coordenou coisas diferentes (nome + oração)? Quebrou o paralelismo. Iguale a estrutura.","erroComum":"Não identificar a assimetria entre nome e oração coordenados.","comoBancaPensa":"Paralelismo é cobrado por meio de reescritura equivalente."}},"PT-012":{"cognitivo":{"motivo":"Cobrar a regência do verbo 'preferir'.","palavraCritica":"preferir A (não 'do que')"},"comentario":{"resolucao":"ERRADO. Na norma-padrão, 'preferir' rege a preposição 'a': prefere-se uma coisa A outra. A construção com 'do que' ('prefiro atuar em campo do que...') é condenada. O correto: 'prefiro atuar em campo a trabalhar no gabinete'.","fundamento":"Gramática normativa — regência do verbo 'preferir'.","macete":"Preferir + 'a'. Sem 'mais', sem 'do que', sem 'antes'.","erroComum":"Usar 'do que' após 'preferir'.","comoBancaPensa":"Regência de 'preferir' é cobrada validando a forma coloquial."}},"PT-013":{"cognitivo":{"motivo":"Distinguir conector causal (uma vez que) de concessivo (ainda que).","palavraCritica":"causa (uma vez que) × concessão (ainda que)"},"comentario":{"resolucao":"ERRADO. 'Uma vez que' introduz relação de CAUSA (equivale a 'porque'); 'ainda que' expressa CONCESSÃO (equivale a 'embora'). A substituição inverteria a relação lógica entre as orações, alterando o sentido do período.","fundamento":"Gramática normativa — conjunções causais e concessivas.","macete":"Uma vez que = porque. Ainda que = embora. São valores opostos.","erroComum":"Trocar conectivos de valores lógicos diferentes por soarem parecidos.","comoBancaPensa":"Substituição de conectivo que altera a relação de sentido — formato nº 1 de Português."}},"PT-014":{"cognitivo":{"motivo":"Cobrar a referência do pronome oblíquo átono.","palavraCritica":"'o' = relatório"},"comentario":{"resolucao":"CERTO. O pronome oblíquo átono 'o', em 'encaminhou-o', retoma 'o relatório' (objeto direto), estabelecendo a coesão: a autoridade recebeu o relatório e o encaminhou ao MP.","fundamento":"Gramática normativa — pronomes oblíquos e coesão referencial.","macete":"'o/a' retoma coisa (objeto). 'lhe' retoma pessoa (objeto indireto).","erroComum":"Atribuir o pronome ao sujeito em vez do objeto.","comoBancaPensa":"Referência pronominal é cobrança recorrente de coesão."}},"PT-015":{"cognitivo":{"motivo":"Cobrar a concordância com sujeito composto anteposto ao verbo.","palavraCritica":"sujeito composto → verbo no plural"},"comentario":{"resolucao":"ERRADO. O sujeito é composto ('O delegado e o escrivão') e antecede o verbo; logo, a concordância exige o plural: 'analisaram'. O emprego no singular ('analisou') viola a norma-padrão.","fundamento":"Gramática normativa — concordância verbal (sujeito composto).","macete":"Sujeito composto antes do verbo = plural. 'A e B analisaram'.","erroComum":"Concordar o verbo com apenas um dos núcleos.","comoBancaPensa":"Sujeito composto anteposto com verbo no singular é isca clássica."}},"PT-016":{"cognitivo":{"motivo":"Cobrar equivalência entre conectivos de mesmo valor semântico (causal).","palavraCritica":"porquanto = porque (causal)"},"comentario":{"resolucao":"CERTO. “Uma vez que” e “porquanto” são conjunções de valor CAUSAL (equivalem a “porque”). A substituição mantém a correção gramatical e a relação de causa entre a necessidade de qualificação dos quadros e a compreensão técnica dos meios digitais.","fundamento":"Gramática normativa — conjunções subordinativas causais.","macete":"Causais: porque, porquanto, uma vez que, já que, visto que — intercambiáveis.","erroComum":"Achar que 'porquanto' tem valor conclusivo.","comoBancaPensa":"Alterna trocas válidas e inválidas de conectivo para testar o valor lógico."}},"PT-017":{"cognitivo":{"motivo":"Distinguir conectivo adversativo de conclusivo.","palavraCritica":"contudo (oposição) × portanto (conclusão)"},"comentario":{"resolucao":"ERRADO. “Contudo” é conectivo ADVERSATIVO: introduz a ressalva de que a técnica não substitui o raciocínio investigativo, contrapondo-se ao parágrafo anterior. “Portanto” é CONCLUSIVO e transformaria a ressalva em consequência, alterando a coerência argumentativa.","fundamento":"Gramática normativa — coordenação (adversativas e conclusivas).","macete":"Contudo = oposição. Portanto = conclusão. Não se trocam.","erroComum":"Substituir conectivos de valores lógicos distintos.","comoBancaPensa":"Troca de conectivo que altera a articulação do argumento — formato nº 1 de Português."}},"PT-018":{"cognitivo":{"motivo":"Cobrar a crase resultante de regência verbal + artigo feminino.","palavraCritica":"preposição 'a' (regência) + artigo 'a' (observância)"},"comentario":{"resolucao":"CERTO. O verbo “submeter-se” rege a preposição “a” (submeter-se A algo), e “observância” é substantivo feminino que admite o artigo “a”. Da fusão resulta a crase: “submete-se à observância do devido processo legal”. O teste do masculino confirma (“submete-se ao cumprimento”).","fundamento":"Gramática normativa — regência verbal e crase.","macete":"Trocou por masculino e virou 'ao'? Então no feminino é 'à'.","erroComum":"Não identificar a preposição exigida pela regência do verbo.","comoBancaPensa":"Reescritura que cria a condição de crase testa regência + artigo simultaneamente."}},"PT-019":{"cognitivo":{"motivo":"Distinguir 'tampouco' (= também não) de 'tão pouco' (intensidade/quantidade).","palavraCritica":"tampouco = também não"},"comentario":{"resolucao":"ERRADO. No contexto, “tampouco” significa “também não” (o domínio das ferramentas não dispensa a análise crítica, nem tampouco a observância das garantias). Já “tão pouco” exprime pequena quantidade/intensidade. As formas não são intercambiáveis: a alteração comprometeria o sentido.","fundamento":"Gramática normativa — semântica e ortografia.","macete":"Cabe 'também não'? Escreve junto: tampouco.","erroComum":"Tratar as formas homófonas como equivalentes.","comoBancaPensa":"Explora pares homófonos de sentidos distintos (tampouco/tão pouco, senão/se não)."}},"PT-020":{"cognitivo":{"motivo":"Cobrar a regra de pontuação da conjunção intercalada/deslocada.","palavraCritica":"contudo intercalado entre vírgulas"},"comentario":{"resolucao":"CERTO. Quando a conjunção adversativa é deslocada de sua posição inicial e intercalada no período, ela deve ser isolada por vírgulas — exatamente o caso de “Não se trata, contudo, de substituir”. A pontuação sinaliza o deslocamento.","fundamento":"Gramática normativa — pontuação de conjunções deslocadas.","macete":"Conjunção no meio da oração = entre vírgulas.","erroComum":"Classificar as vírgulas como isoladoras de aposto.","comoBancaPensa":"Pede a JUSTIFICATIVA da vírgula, não apenas se ela está correta."}},"PT-021":{"cognitivo":{"motivo":"Cobrar o valor semântico do conectivo 'ou seja'.","palavraCritica":"ou seja"},"comentario":{"resolucao":"CERTO. A expressão 'ou seja' tem valor explicativo: retoma 'cadeia de custódia' e a define ('o conjunto de procedimentos que garante a rastreabilidade...'), função típica desse conectivo.","fundamento":"Gramática — classe dos conectivos explicativos.","macete":"Conectivo explicativo = reformula/define o termo anterior.","erroComum":"Atribuir valor adversativo ou condicional ao conectivo.","comoBancaPensa":"Item de fixação sobre o valor semântico de conectivos textuais."}},"PT-022":{"cognitivo":{"motivo":"Cobrar a classificação de orações subordinadas adverbiais.","palavraCritica":"Quando"},"comentario":{"resolucao":"CERTO. 'Quando essa cadeia é rompida' é oração subordinada adverbial temporal, pois situa no tempo a circunstância em que ocorre o fato descrito na oração principal ('abre-se margem para que a defesa questione...').","fundamento":"Gramática — orações subordinadas adverbiais (classificação).","macete":"Quando = sempre temporal, nunca condicional.","erroComum":"Classificar 'quando' como conjunção condicional.","comoBancaPensa":"Item clássico de classificação de orações."}},"PT-023":{"cognitivo":{"motivo":"Cobrar a regência correta do verbo 'questionar'.","palavraCritica":"transitivo indireto"},"comentario":{"resolucao":"ERRADO. O verbo 'questionar', no trecho, é transitivo DIRETO ('questionar algo'), e não indireto — o complemento 'a idoneidade da prova' completa o verbo sem preposição exigida por ele.","fundamento":"Gramática — regência verbal (transitividade).","macete":"Questionar algo = VTD. Não confundir com verbos que exigem preposição (ex.: 'duvidar DE algo').","erroComum":"Classificar 'questionar' como VTI por analogia com verbos similares que exigem preposição.","comoBancaPensa":"Testa se o candidato verifica a real regência antes de aceitar a classificação proposta."}},"PT-024":{"cognitivo":{"motivo":"Cobrar a justificativa correta do uso da crase.","palavraCritica":"à disciplina"},"comentario":{"resolucao":"CERTO. A crase em 'à disciplina' resulta da regência de 'sujeitar-se a' (que exige a preposição 'a') combinada com o artigo feminino que acompanha 'disciplina', configurando corretamente a fusão preposição+artigo.","fundamento":"Gramática — regras de crase (fusão de preposição e artigo).","macete":"Verbo/nome que rege 'a' + palavra feminina determinada por artigo = crase.","erroComum":"Negar a crase por não perceber a regência do verbo pronominal.","comoBancaPensa":"Testa o raciocínio completo de justificativa da crase, não apenas o reconhecimento do acento."}},"PT-025":{"cognitivo":{"motivo":"Cobrar a identificação correta do sujeito gramatical.","palavraCritica":"sujeito composto"},"comentario":{"resolucao":"ERRADO. O sujeito de 'substitui' é apenas 'nenhuma inovação' (sujeito simples, singular) — 'tecnologia' integra outra oração do mesmo período ('Ainda que a tecnologia tenha avançado...'), não compondo o sujeito da oração em análise. A concordância no singular está correta.","fundamento":"Gramática — concordância verbal (identificação do sujeito).","macete":"Delimite a oração antes de identificar o sujeito — não misture orações do mesmo período.","erroComum":"Somar elementos de orações diferentes para 'criar' um sujeito composto inexistente.","comoBancaPensa":"Testa se o candidato delimita corretamente os limites oracionais antes de analisar a concordância."}},"PT-026":{"cognitivo":{"motivo":"Cobrar a distinção entre informação acessória (exemplificativa) e essencial.","palavraCritica":"informação essencial ... comprometeria"},"comentario":{"resolucao":"ERRADO. O trecho isolado pelos travessões é um aposto explicativo de natureza exemplificativa ('a exemplo de'), portanto acessório: sua supressão não compromete a estrutura sintática do período ('Ainda que a tecnologia tenha avançado significativamente nas últimas décadas, nenhuma inovação substitui...' permanece completo e correto).","fundamento":"Gramática — pontuação (travessão e aposto explicativo).","macete":"Exemplo entre travessões/vírgulas = acessório, suprimível sem quebrar a sintaxe.","erroComum":"Considerar todo aposto como 'essencial' apenas por conter informação relevante.","comoBancaPensa":"Restringe indevidamente o caráter acessório do aposto exemplificativo."}},"PT-027":{"cognitivo":{"motivo":"Cobrar o valor semântico do advérbio/conectivo 'afinal'.","palavraCritica":"Afinal"},"comentario":{"resolucao":"CERTO. 'Afinal', no período final, introduz a justificativa da afirmação anterior (a insubstituibilidade da disciplina metodológica), com valor semântico conclusivo/explicativo, equivalente a 'pois' ou 'com efeito'.","fundamento":"Gramática — valores semânticos de conectivos e advérbios.","macete":"'Afinal' explicativo = justifica; não confundir com o sentido temporal de 'por fim'.","erroComum":"Atribuir a 'afinal' valor adversativo ou puramente temporal.","comoBancaPensa":"Item de fixação sobre polissemia de conectivos comuns."}},"PT-028":{"cognitivo":{"motivo":"Cobrar a regência nominal correta do substantivo 'idoneidade'.","palavraCritica":"desvio de regência"},"comentario":{"resolucao":"ERRADO. O substantivo 'idoneidade' rege-se corretamente pela preposição 'de' ('idoneidade de algo'), como empregado no texto ('idoneidade da prova' = idoneidade + de + a prova). Não existe, na norma-padrão, exigência de regência pela preposição 'a' para esse substantivo — a afirmação cria uma exigência inexistente.","fundamento":"Gramática — regência nominal.","macete":"Idoneidade DE (algo/alguém) — regência consagrada, sem variação.","erroComum":"Aceitar uma regra de regência fabricada sem verificar o uso padrão real.","comoBancaPensa":"Cria uma exigência gramatical que não existe, testando se o candidato a aceita sem questionar."}},"PT-029":{"cognitivo":{"motivo":"Cobrar o valor circunstancial correto de orações reduzidas de gerúndio.","palavraCritica":"concessiva"},"comentario":{"resolucao":"ERRADO. A oração reduzida de gerúndio expressa circunstância de MODO (indica como os peritos cumprem a disciplina metodológica), e não concessão — não há, no trecho, qualquer ideia de contraste ou oposição que justificasse a equivalência com 'embora registrem'.","fundamento":"Gramática — orações reduzidas (valores circunstanciais do gerúndio).","macete":"Gerúndio descrevendo 'como' a ação principal se realiza = modo.","erroComum":"Atribuir valor concessivo a qualquer oração reduzida de gerúndio, independentemente do contexto.","comoBancaPensa":"Testa a real compreensão do valor circunstancial, não apenas o reconhecimento da forma verbal."}},"PT-030":{"cognitivo":{"motivo":"Cobrar a função das vírgulas na construção de apostos explicativos.","palavraCritica":"aposto explicativo"},"comentario":{"resolucao":"CERTO. As vírgulas isolam corretamente um aposto explicativo, introduzido pela expressão 'ou seja', que retoma e define o termo 'cadeia de custódia' mencionado anteriormente.","fundamento":"Gramática — pontuação (vírgula em aposto explicativo).","macete":"Vírgula antes e depois de 'ou seja' = sinal de aposto explicativo.","erroComum":"Não identificar a estrutura apositiva isolada por vírgulas.","comoBancaPensa":"Item de fixação sobre a função sintática da pontuação."}},"PT-031":{"cognitivo":{"motivo":"Cobrar a distinção entre voz passiva sintética e indeterminação do sujeito.","palavraCritica":"sujeito indeterminado"},"comentario":{"resolucao":"ERRADO. Trata-se de voz passiva sintética (pronome apassivador 'se'), e não de indeterminação do sujeito: o verbo 'abrir' é transitivo direto ('abrir margem'), e 'margem' funciona como sujeito paciente, concordando corretamente no singular com 'abre-se'.","fundamento":"Gramática — funções do 'se' (voz passiva sintética × indeterminação do sujeito).","macete":"Se o substantivo após o 'se' concorda em número com o verbo, é voz passiva sintética — não indeterminação.","erroComum":"Classificar toda construção com 'se' e verbo intransitivo aparente como indeterminação do sujeito.","comoBancaPensa":"Testa a distinção fina entre as duas funções mais confundidas do 'se' na sintaxe portuguesa."}},"PT-032":{"cognitivo":{"motivo":"Cobrar a identificação da tipologia textual predominante.","palavraCritica":"dissertativo-argumentativa"},"comentario":{"resolucao":"CERTO. O texto é predominantemente dissertativo-argumentativo: expõe informações técnicas sobre a cadeia de custódia e defende, com justificativas explícitas ('Por essa razão', 'Afinal'), a tese de que nenhuma tecnologia substitui a disciplina metodológica na cena do crime.","fundamento":"Teoria da comunicação — tipologia textual (dissertação argumentativa).","macete":"Presença de tese + justificativas + conectivos argumentativos = dissertativo-argumentativo.","erroComum":"Classificar o texto como meramente expositivo/descritivo, ignorando a defesa de tese.","comoBancaPensa":"Item de fixação sobre reconhecimento de tipologia textual predominante."}},"PT-033":{"cognitivo":{"motivo":"Fixar o pareamento entre os dois sentidos.","palavraCritica":"denotativo ... conotativo"},"comentario":{"resolucao":"CERTO. O sentido denotativo é o literal, dicionarizado e objetivo; o conotativo é o figurado, construído por associações subjetivas e dependente do contexto.","fundamento":"Semântica — denotação e conotação.","macete":"Denota = dicionário.","erroComum":"Inverter os conceitos.","comoBancaPensa":"Par correto entre termos foneticamente próximos."}},"PT-034":{"cognitivo":{"motivo":"Fixar a distinção entre os dois mecanismos textuais.","palavraCritica":"formal ... lógica de sentido"},"comentario":{"resolucao":"CERTO. A coesão opera na superfície textual, pelos mecanismos de referência, substituição, elipse e conexão; a coerência situa-se no plano do sentido, garantindo unidade lógica ao texto. São independentes: há textos coesos porém incoerentes.","fundamento":"Linguística textual — coesão e coerência.","macete":"Coesão = forma; coerência = sentido.","erroComum":"Tratar como sinônimos.","comoBancaPensa":"Par correto entre conceitos que o candidato costuma fundir."}},"PT-035":{"cognitivo":{"motivo":"Cobrar a distinção entre frase e oração, que sustenta toda a análise sintática posterior.","palavraCritica":"pode constituir-se sem verbo algum"},"comentario":{"resolucao":"CERTO. Frase é todo enunciado com sentido completo, com ou sem verbo — as frases nominais são o caso típico (\"Silêncio!\", \"Que sufoco!\"). Oração é a unidade construída em torno de um verbo ou locução verbal, tenha ou não sentido completo. Período é a frase formada por uma ou mais orações, encerrado por pontuação forte.","fundamento":"Nomenclatura Gramatical Brasileira — frase, oração e período.","macete":"Frase pode não ter verbo. Oração tem que ter. Período é frase com oração.","erroComum":"Usar frase e oração como sinônimos.","comoBancaPensa":"Item 'limpo' de conceituação, que abre o bloco de sintaxe."}},"PT-036":{"cognitivo":{"motivo":"Cobrar os mesmos conceitos com os rótulos permutados.","palavraCritica":"oração ... sem verbo"},"comentario":{"resolucao":"ERRADO. As definições estão trocadas. Quem prescinde de verbo é a FRASE; quem se organiza obrigatoriamente em torno de um verbo é a ORAÇÃO. \"Fogo!\" é frase e não é oração; \"que o delegado assinasse o auto\" é oração e, isolada, não tem sentido completo.","fundamento":"Nomenclatura Gramatical Brasileira — frase e oração.","macete":"Sentido completo → frase. Verbo → oração. São critérios diferentes.","erroComum":"Trocar o critério de cada conceito.","comoBancaPensa":"Permuta duas definições que o candidato reconhece isoladamente, mas não sabe atribuir."}},"PT-037":{"cognitivo":{"motivo":"Contraexemplo: dois conceitos vizinhos aplicados corretamente a exemplos distintos.","palavraCritica":"oração absoluta"},"comentario":{"resolucao":"CERTO. O período simples tem uma só oração, chamada absoluta justamente por não se subordinar nem se coordenar a nenhuma outra. O período composto tem duas ou mais — no segundo exemplo, \"lavrou\" e \"chegou\", esta última introduzida pela locução conjuntiva temporal \"assim que\". A contagem de orações segue a contagem de verbos ou locuções verbais.","fundamento":"Nomenclatura Gramatical Brasileira — período simples e composto; oração absoluta.","macete":"Um verbo, um período simples. Dois ou mais, composto.","erroComum":"Desconhecer o termo 'oração absoluta' e supor que seja erro.","comoBancaPensa":"Apresenta corretamente um par de conceitos que costuma inverter, para separar quem sabe de quem responde por padrão."}},"PT-038":{"cognitivo":{"motivo":"Cobrar que a locução verbal conta como uma única oração.","palavraCritica":"quatro orações"},"comentario":{"resolucao":"ERRADO. São duas orações, não quatro. \"Tinha analisado\" e \"havia concluído\" são locuções verbais: cada uma reúne verbo auxiliar e principal em torno de um só núcleo verbal. A regra correta é contar verbos e locuções verbais — e a locução, por mais formas que reúna, vale por uma.","fundamento":"Nomenclatura Gramatical Brasileira — locução verbal e contagem de orações.","macete":"Locução verbal é um só núcleo. Auxiliar + principal = uma oração.","erroComum":"Contar auxiliar e principal como orações distintas.","comoBancaPensa":"Multiplica a contagem apoiando-se numa regra formulada de modo quase correto ('cada forma verbal')."}},"PT-039":{"cognitivo":{"motivo":"Cobrar que a classificação do sujeito depende do número de núcleos, e não da extensão do termo.","palavraCritica":"por possuir núcleo único"},"comentario":{"resolucao":"CERTO. O que define sujeito simples ou composto é a quantidade de NÚCLEOS, não de palavras. No segundo exemplo, \"Os agentes experientes\" tem um único núcleo — \"agentes\" —, acompanhado de dois adjuntos adnominais; segue simples, por mais longo que seja. No primeiro, há dois núcleos: \"agentes\" e \"delegado\".","fundamento":"Nomenclatura Gramatical Brasileira — sujeito simples e composto.","macete":"Conte núcleos, não palavras. Sujeito longo pode ser simples.","erroComum":"Classificar como composto todo sujeito com muitas palavras.","comoBancaPensa":"Contrapõe dois exemplos para checar se o candidato aplica o critério certo."}},"PT-040":{"cognitivo":{"motivo":"Cobrar a diferença entre sujeito ausente e sujeito impossível de identificar.","palavraCritica":"indeterminado ... não figura expresso"},"comentario":{"resolucao":"ERRADO. O sujeito de \"recolheram\" é perfeitamente identificável no próprio período: são \"os peritos\". Trata-se, portanto, de sujeito OCULTO (elíptico ou desinencial), e não indeterminado. Indeterminado é aquele que existe, mas não se pode identificar nem pelo contexto nem pela desinência — como em \"Recolheram os vestígios\", isolado.","fundamento":"Nomenclatura Gramatical Brasileira — sujeito oculto e sujeito indeterminado.","macete":"Dá para dizer quem é pelo contexto? Oculto. Não dá de jeito nenhum? Indeterminado.","erroComum":"Tomar 'verbo na 3ª pessoa do plural' como sinal automático de indeterminação.","comoBancaPensa":"Isola a segunda oração do contexto que a determina, esperando que o candidato faça o mesmo."}},"PT-041":{"cognitivo":{"motivo":"Contraexemplo: o par indeterminado/oculto aplicado corretamente a dois contextos.","palavraCritica":"enunciado isoladamente"},"comentario":{"resolucao":"CERTO. A classificação depende do contexto, e o item o explicita. Sem referência anterior, \"Arrombaram\" na 3ª pessoa do plural deixa o agente irrecuperável: sujeito indeterminado. Com a referência dada — \"A guarnição\" —, o sujeito de \"arrombou\" é recuperável: oculto. O mesmo verbo muda de classificação conforme o entorno.","fundamento":"Nomenclatura Gramatical Brasileira — sujeito indeterminado e sujeito oculto.","macete":"Verbo na 3ª do plural sem dono no contexto: indeterminado. Com dono citado antes: oculto.","erroComum":"Marcar ERRADO por desconfiar de item que compara duas classificações.","comoBancaPensa":"Apresenta corretamente um par que costuma inverter, punindo quem responde pelo formato do enunciado."}},"PT-042":{"cognitivo":{"motivo":"Cobrar o SE com verbo transitivo indireto, que não admite flexão no plural.","palavraCritica":"ainda que ... esteja no plural"},"comentario":{"resolucao":"CERTO. \"Necessitar\" é transitivo indireto e \"de peritos criminais\" é objeto indireto — não sujeito. Como o SE aqui indetermina o sujeito, o verbo fica invariavelmente na 3ª pessoa do singular. Escrever \"Necessitam-se de peritos\" é erro clássico, por atrair o verbo a um termo que não é sujeito.","fundamento":"Gramática normativa — pronome indeterminador do sujeito com verbos transitivos indiretos.","macete":"Sobrou preposição depois do SE? Verbo no singular, sempre.","erroComum":"Flexionar o verbo pelo objeto indireto.","comoBancaPensa":"Item correto que exige identificar a transitividade antes de decidir a concordância."}},"PT-043":{"cognitivo":{"motivo":"Cobrar a distinção entre partícula apassivadora e índice de indeterminação, decidida pela transitividade.","palavraCritica":"voz passiva sintética ... sujeito paciente"},"comentario":{"resolucao":"ERRADO. A voz passiva sintética só se forma com verbo transitivo DIRETO. \"Precisar\", no sentido de necessitar, é transitivo indireto — e a presença da preposição \"de\" o denuncia. Logo, o SE é índice de indeterminação do sujeito, \"de novos escrivães\" é objeto indireto e o verbo fica no singular.","fundamento":"Gramática normativa — partícula apassivadora (VTD) x índice de indeterminação do sujeito (VTI).","macete":"Tem preposição? Indetermina e fica singular. Não tem? Apassiva e concorda.","erroComum":"Ver o 'se' e presumir voz passiva sintética.","comoBancaPensa":"Aplica a análise correta de uma estrutura à estrutura vizinha, que exige análise oposta."}},"PT-044":{"cognitivo":{"motivo":"Cobrar a voz passiva sintética com verbo transitivo direto e a concordância dela decorrente.","palavraCritica":"exerce a função de sujeito"},"comentario":{"resolucao":"CERTO. \"Apreender\" é transitivo direto; o SE apassiva, e a oração equivale a \"Dezenas de aparelhos celulares foram apreendidas na operação\". Como o termo é sujeito, o verbo concorda com ele. O teste é sempre esse: se a frase admite conversão para a passiva analítica, o SE é apassivador.","fundamento":"Gramática normativa — voz passiva sintética ou pronominal.","macete":"Converta para 'foi/foram + particípio'. Deu certo? É apassivadora e concorda.","erroComum":"Deixar o verbo no singular por não reconhecer o sujeito posposto.","comoBancaPensa":"Item correto que cobra a cadeia inteira: transitividade, função do SE e concordância."}},"PT-045":{"cognitivo":{"motivo":"Cobrar a concordância na voz passiva sintética, contra a generalização do singular.","palavraCritica":"invariavelmente ... singular"},"comentario":{"resolucao":"ERRADO. \"Divulgar\" é transitivo direto, de modo que o SE é apassivador e \"os resultados do concurso\" é sujeito — o verbo deve concordar: \"Divulgaram-se os resultados do concurso\". A invariabilidade no singular vale apenas quando o SE indetermina o sujeito, com verbo transitivo indireto, intransitivo ou de ligação.","fundamento":"Gramática normativa — concordância na voz passiva sintética.","macete":"VTD com 'se': concorda. VTI com 'se': fica no singular.","erroComum":"Aplicar o singular a todas as construções com 'se'.","comoBancaPensa":"Toma a regra de um caso e a estende a todos com 'invariavelmente'."}},"PT-046":{"cognitivo":{"motivo":"Contraexemplo: um 'sempre' verdadeiro, com a consequência sintática correta.","palavraCritica":"sempre ... objeto direto, e não sujeito"},"comentario":{"resolucao":"CERTO. \"Haver\" existencial não tem sujeito: a oração é sem sujeito e o verbo fica travado no singular — \"Havia denúncias\", nunca \"Haviam denúncias\". O termo que parece sujeito é objeto direto. A impessoalidade se transmite ao auxiliar em locuções: \"Pode haver denúncias\", e não \"Podem haver\".","fundamento":"Gramática normativa — impessoalidade do verbo haver no sentido existencial.","macete":"Haver de existir não tem sujeito: singular sempre, e o resto é objeto direto.","erroComum":"Marcar ERRADO por reflexo diante de 'sempre', ou flexionar o verbo pelo objeto.","comoBancaPensa":"Usa advérbio absoluto em regra que realmente não admite exceção."}},"PT-047":{"cognitivo":{"motivo":"Cobrar que apenas o haver existencial é impessoal, e não seus sinônimos.","palavraCritica":"existir, ocorrer e acontecer são impessoais"},"comentario":{"resolucao":"ERRADO. Existir, ocorrer e acontecer são verbos PESSOAIS: têm sujeito e com ele concordam. O correto é \"Ocorreram diversas irregularidades no certame\", em que \"diversas irregularidades\" é sujeito. A impessoalidade é privilégio do haver existencial — e é exatamente por isso que a banca oferece os sinônimos como armadilha.","fundamento":"Gramática normativa — haver impessoal x existir/ocorrer/acontecer pessoais.","macete":"Só o HAVER é impessoal. Trocou por existir/ocorrer/acontecer, o verbo passa a concordar.","erroComum":"Estender a impessoalidade do haver aos verbos de sentido equivalente.","comoBancaPensa":"Usa a sinonímia semântica para induzir à identidade sintática, que não existe."}},"PT-048":{"cognitivo":{"motivo":"Contraexemplo: o par haver/ocorrer analisado corretamente, com a consequência na flexão.","palavraCritica":"explica a diferença de flexão"},"comentario":{"resolucao":"CERTO. As duas frases dizem o mesmo e se analisam de modo oposto. Com \"haver\", não há sujeito e o verbo trava no singular; \"falhas\" é objeto direto. Com \"ocorrer\", há sujeito — \"falhas\" — e o verbo concorda no plural. É a demonstração de que sinonímia semântica não implica identidade sintática.","fundamento":"Gramática normativa — verbo haver impessoal e verbo ocorrer pessoal.","macete":"Houve falhas / Ocorreram falhas. Mesmo sentido, análise oposta.","erroComum":"Marcar ERRADO por desconfiar de item que contrasta duas construções.","comoBancaPensa":"Apresenta corretamente o contraste que costuma servir de armadilha, para checar compreensão real."}},"PT-049":{"cognitivo":{"motivo":"Cobrar o caso mais direto de oração sem sujeito, com a ressalva 'em regra'.","palavraCritica":"em regra"},"comentario":{"resolucao":"CERTO. Verbos de fenômeno natural não atribuem ação a ninguém: não há de quem se predicar. A ressalva \"em regra\" é o que torna o item exato, pois esses verbos deixam de ser impessoais quando empregados em sentido figurado.","fundamento":"Nomenclatura Gramatical Brasileira — orações sem sujeito.","macete":"Choveu, nevou, anoiteceu: ninguém fez. Oração sem sujeito.","erroComum":"Apontar um sujeito oculto ('ele') onde não há sujeito algum.","comoBancaPensa":"Item correto cuja ressalva 'em regra' prepara a generalização indevida do item seguinte."}},"PT-050":{"cognitivo":{"motivo":"Cobrar a perda da impessoalidade no emprego figurado.","palavraCritica":"em qualquer contexto"},"comentario":{"resolucao":"ERRADO. Em sentido figurado, esses verbos se tornam pessoais e passam a ter sujeito: em \"Choveram críticas sobre a corporação\", o sujeito é \"críticas\" — tanto que o verbo está no plural, concordando com ele. O mesmo ocorre em \"Amanheci indisposto\", com sujeito desinencial \"eu\". A impessoalidade vale para o sentido literal.","fundamento":"Gramática normativa — verbos de fenômeno natural em sentido figurado.","macete":"Choveu água: sem sujeito. Choveram críticas: sujeito é 'críticas'.","erroComum":"Aplicar a regra pelo verbo, sem olhar o sentido.","comoBancaPensa":"Converte uma regra com exceção conhecida em regra absoluta, com 'qualquer contexto'."}},"PT-051":{"cognitivo":{"motivo":"Cobrar a impessoalidade de fazer e haver em expressões temporais, item de altíssima recorrência.","palavraCritica":"e não \"Fazem cinco anos\""},"comentario":{"resolucao":"CERTO. Indicando tempo decorrido, \"fazer\" e \"haver\" não têm sujeito e ficam na 3ª pessoa do singular. A expressão de tempo é adjunto adverbial, não sujeito — daí a impossibilidade de flexionar o verbo. A impessoalidade contamina o auxiliar: \"Deve fazer cinco anos\", nunca \"Devem fazer\".","fundamento":"Gramática normativa — verbos fazer e haver impessoais na indicação de tempo.","macete":"Faz cinco anos, faz dois meses, faz séculos. Nunca 'fazem'.","erroComum":"Concordar o verbo com a expressão numérica de tempo.","comoBancaPensa":"Item 'limpo' que a banca repete em quase toda prova de nível médio."}},"PT-052":{"cognitivo":{"motivo":"Cobrar a função sintática da expressão temporal, que não é sujeito.","palavraCritica":"função de sujeito"},"comentario":{"resolucao":"ERRADO. \"Havia\", indicando tempo decorrido, é impessoal: a oração não tem sujeito e a expressão \"três meses\" é adjunto adverbial de tempo. Por isso o verbo não se flexiona — \"Haviam três meses\" contraria a norma-padrão. A posição inicial do termo é justamente o que induz a lê-lo como sujeito.","fundamento":"Gramática normativa — impessoalidade do verbo haver na indicação de tempo decorrido.","macete":"Expressão de tempo depois de faz/há é adjunto adverbial, nunca sujeito.","erroComum":"Ler como sujeito todo termo que antecede ou segue de perto o verbo.","comoBancaPensa":"Atribui função de sujeito a um adjunto adverbial, para justificar uma flexão indevida."}},"PT-053":{"cognitivo":{"motivo":"Contraexemplo: uma aparente contradição — impessoal e ainda assim flexionado — que é exatamente a regra.","palavraCritica":"impessoal, mas concorda"},"comentario":{"resolucao":"CERTO. É o caso singular em que o verbo, sem sujeito, concorda com o predicativo numérico: uma hora leva o singular; quinze horas levam o plural. O mesmo vale para datas e distâncias — \"São dois quilômetros até a delegacia\". O item parece contraditório e não é: a concordância se faz com a expressão de hora, embora não haja sujeito.","fundamento":"Gramática normativa — verbo ser na indicação de horas, datas e distâncias.","macete":"É uma hora. São duas horas. Sem sujeito, mas concordando com o número.","erroComum":"Marcar ERRADO por achar impossível verbo impessoal flexionar-se no plural.","comoBancaPensa":"Explora a aparência de contradição de uma regra que o candidato aplica sem conhecer."}},"PT-054":{"cognitivo":{"motivo":"Cobrar a classificação dos três tipos de predicado pelo critério do núcleo.","palavraCritica":"dois núcleos"},"comentario":{"resolucao":"CERTO. O critério é sempre o núcleo. Em \"O delegado indiciou o suspeito\", o núcleo é \"indiciou\": predicado verbal. Em \"O delegado está convicto\", o núcleo é \"convicto\": predicado nominal. Em \"O delegado saiu convicto\", há dois — \"saiu\" e \"convicto\": predicado verbo-nominal. Note que no verbo-nominal o verbo é transitivo ou intransitivo, nunca de ligação.","fundamento":"Nomenclatura Gramatical Brasileira — tipos de predicado.","macete":"Um núcleo verbal: verbal. Um núcleo predicativo: nominal. Dois núcleos: verbo-nominal.","erroComum":"Classificar pelo tipo de verbo, e não pelo núcleo do predicado.","comoBancaPensa":"Item 'limpo' de definição, âncora para as trocas que virão."}},"PT-055":{"cognitivo":{"motivo":"Cobrar o reconhecimento de verbo de ligação fora da lista óbvia (ser, estar).","palavraCritica":"núcleo é a forma verbal \"permaneceu\""},"comentario":{"resolucao":"ERRADO. \"Permanecer\" é verbo de ligação: não exprime ação, mas estado permanente, e liga o sujeito à característica \"atenta\". O núcleo do predicado é o predicativo \"atenta\", de modo que o predicado é NOMINAL. Integram a mesma lista ser, estar, ficar, continuar, andar, tornar-se e parecer — variáveis conforme o contexto.","fundamento":"Nomenclatura Gramatical Brasileira — predicado nominal e verbos de ligação.","macete":"Verbo que não indica ação, mas estado, é de ligação. O núcleo passa a ser o predicativo.","erroComum":"Reconhecer como verbo de ligação apenas 'ser' e 'estar'.","comoBancaPensa":"Escolhe um verbo de ligação menos evidente para que o candidato o tome por verbo de ação."}},"PT-056":{"cognitivo":{"motivo":"Contraexemplo: análise correta de uma estrutura que a banca costuma classificar como adjunto adverbial de modo.","palavraCritica":"predicativo do sujeito \"nervosa\""},"comentario":{"resolucao":"CERTO. \"Nervosa\" não modifica o verbo — atribui estado à testemunha, e por isso é predicativo do sujeito, concordando com ele em gênero e número. Como \"chegou\" mantém seu valor de ação e há também o predicativo, o predicado tem dois núcleos: verbo-nominal. O teste decisivo é a flexão: adjunto adverbial de modo seria invariável (\"chegou nervosamente\").","fundamento":"Nomenclatura Gramatical Brasileira — predicado verbo-nominal e predicativo do sujeito.","macete":"Palavra que concorda com o sujeito é predicativo. Invariável é adjunto adverbial.","erroComum":"Classificar 'nervosa' como adjunto adverbial de modo.","comoBancaPensa":"Apresenta corretamente a análise que costuma distorcer, checando se o candidato aplica o teste de flexão."}},"PT-057":{"cognitivo":{"motivo":"Cobrar o mesmo teste do item anterior, agora com a classificação errada.","palavraCritica":"adjunto adverbial de modo"},"comentario":{"resolucao":"ERRADO. \"Exaustos\" flexiona-se em gênero e número para concordar com \"Os investigadores\" — prova de que se refere ao sujeito, e não ao verbo. Trata-se de predicativo do sujeito, e o predicado é verbo-nominal. Adjunto adverbial é invariável: \"retornaram rapidamente\" não muda de forma, ainda que o sujeito seja feminino ou singular.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do sujeito x adjunto adverbial.","macete":"Varia com o sujeito? Predicativo. Não varia? Adjunto adverbial.","erroComum":"Classificar pelo sentido ('indica como') sem aplicar o teste de flexão.","comoBancaPensa":"Oferece uma justificativa semântica plausível para encobrir o critério formal correto."}},"PT-058":{"cognitivo":{"motivo":"Cobrar que a classificação verbal depende do emprego, e não de lista fixa.","palavraCritica":"conforme o contexto"},"comentario":{"resolucao":"CERTO. Não existe verbo de ligação por natureza — existe emprego como verbo de ligação. Em \"ficou apreensivo\", o verbo apenas conecta o sujeito ao estado, sem carga semântica própria: predicado nominal. Em \"ficou na viatura\", significa permanecer em um lugar, tem sentido pleno e o termo seguinte é adjunto adverbial: predicado verbal.","fundamento":"Gramática normativa — verbos de ligação e sua dependência contextual.","macete":"Ligação é função, não etiqueta fixa. Analise o emprego, não a lista.","erroComum":"Decorar a lista de verbos de ligação e aplicá-la sem análise.","comoBancaPensa":"Item correto que cobra o método, e não a memorização."}},"PT-059":{"cognitivo":{"motivo":"Cobrar a ocorrência de predicativo do sujeito também no predicado verbo-nominal.","palavraCritica":"indispensável ... verbo de ligação"},"comentario":{"resolucao":"ERRADO. O predicativo do sujeito também aparece no predicado verbo-nominal, em que o verbo é transitivo ou intransitivo — jamais de ligação. Em \"A vítima saiu ilesa do acidente\", \"ilesa\" é predicativo do sujeito e \"saiu\" é intransitivo. A presença de verbo de ligação é indispensável apenas no predicado nominal.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do sujeito nos predicados nominal e verbo-nominal.","macete":"Predicativo do sujeito cabe em dois predicados: nominal e verbo-nominal.","erroComum":"Associar predicativo exclusivamente a verbo de ligação.","comoBancaPensa":"Cria uma exigência que exclui, sem razão, metade das ocorrências do fenômeno."}},"PT-060":{"cognitivo":{"motivo":"Cobrar a variedade de classes que exercem a função de predicativo.","palavraCritica":"locução adjetiva"},"comentario":{"resolucao":"CERTO. Predicativo é função sintática, e várias classes podem preenchê-la: adjetivo (\"reincidente\"), substantivo (\"advogado\"), numeral (\"Os presos eram três\"), pronome (\"Justiça é isso\") e locução adjetiva (\"está sem defensor\"). Confundir classe gramatical com função sintática é o erro que o item cobra.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo e classes que o representam.","macete":"Predicativo é função. Quem a preenche pode ser de várias classes.","erroComum":"Exigir que o predicativo seja necessariamente adjetivo.","comoBancaPensa":"Item correto que separa o plano morfológico do sintático."}},"PT-061":{"cognitivo":{"motivo":"Cobrar a mesma matéria pela restrição indevida da classe.","palavraCritica":"somente ... adjetivos"},"comentario":{"resolucao":"ERRADO. Substantivos exercem a função com frequência — em \"Meu pai foi delegado\", \"delegado\" é predicativo do sujeito e é substantivo. Também numerais, pronomes e locuções adjetivas a exercem. A restrição confunde a classe gramatical mais comum com a única possível.","fundamento":"Nomenclatura Gramatical Brasileira — classes que exercem a função de predicativo.","macete":"Substantivo também predica: 'Ele é escrivão' tem predicativo substantivo.","erroComum":"Igualar 'atribuir característica' a 'ser adjetivo'.","comoBancaPensa":"Restringe a função a uma só classe, com justificativa que parece razoável."}},"PT-062":{"cognitivo":{"motivo":"Cobrar o predicativo do objeto com verbo de valor avaliativo.","palavraCritica":"atribuindo ao objeto ... juízo de valor"},"comentario":{"resolucao":"CERTO. Verbos como considerar, julgar, achar, nomear, eleger e declarar são avaliadores: o termo que os acompanha atribui característica ao objeto, não ao sujeito. \"Improcedente\" concorda com \"a representação\" — o objeto —, e não com \"O conselho\". O predicado é verbo-nominal, com núcleos \"considerou\" e \"improcedente\".","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do objeto direto.","macete":"Considerar, julgar, achar, nomear: o que vem depois qualifica o objeto.","erroComum":"Ler o predicativo do objeto como predicativo do sujeito.","comoBancaPensa":"Item correto que exige identificar a quem a característica se refere."}},"PT-063":{"cognitivo":{"motivo":"Cobrar a mesma estrutura com a atribuição invertida.","palavraCritica":"predicativo do sujeito"},"comentario":{"resolucao":"ERRADO. \"Inidôneo\" qualifica \"o fornecedor\", que é o objeto direto — não \"A comissão\". Trata-se de predicativo do objeto direto. A concordância confirma: o adjetivo está no masculino singular, acompanhando \"fornecedor\", e não o feminino \"comissão\". Quem julga não é inidôneo; quem foi julgado é.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do objeto direto.","macete":"Veja com quem o adjetivo concorda. É ele que aponta a quem se refere.","erroComum":"Presumir que todo predicativo se refere ao sujeito.","comoBancaPensa":"Inverte o alvo do predicativo, com justificativa que soa lógica se ignorada a concordância."}},"PT-064":{"cognitivo":{"motivo":"Contraexemplo: uma restrição de aparência arbitrária que a NGB efetivamente adota.","palavraCritica":"apenas com o verbo chamar"},"comentario":{"resolucao":"CERTO. A restrição é real. O verbo \"chamar\", no sentido de denominar, admite dupla regência: \"Chamaram o réu de inocente\" (objeto direto e predicativo do objeto direto) e \"Chamaram ao réu de inocente\" (objeto indireto e predicativo do objeto indireto). É o único caso reconhecido pela NGB para essa função — daí o \"apenas\", que não é exagero de banca.","fundamento":"Nomenclatura Gramatical Brasileira — predicativo do objeto indireto e a dupla regência de chamar.","macete":"Predicativo do objeto indireto: só com 'chamar' no sentido de denominar.","erroComum":"Marcar ERRADO por reflexo diante de 'apenas', ou desconhecer a dupla regência de chamar.","comoBancaPensa":"Veste de armadilha uma exclusividade que a nomenclatura oficial de fato consagra."}},"PT-065":{"cognitivo":{"motivo":"Cobrar o critério de distinção entre as duas transitividades.","palavraCritica":"sem preposição obrigatória"},"comentario":{"resolucao":"CERTO. Em \"O delegado indiciou o suspeito\", \"indiciar\" é transitivo direto e \"o suspeito\" é objeto direto, sem preposição. Em \"O delegado discordou do laudo\", \"discordar\" é transitivo indireto e exige a preposição \"de\". Note a formulação precisa: \"sem preposição OBRIGATÓRIA\" — porque o objeto direto pode vir preposicionado em casos específicos, sem que a preposição seja exigida pelo verbo.","fundamento":"Nomenclatura Gramatical Brasileira — predicação verbal.","macete":"Pergunte 'o quê/quem' (direto) ou 'de quê/a quem' (indireto).","erroComum":"Deduzir a transitividade pelo sentido, sem testar a pergunta.","comoBancaPensa":"Item correto cuja precisão ('obrigatória') prepara o item sobre objeto direto preposicionado."}},"PT-066":{"cognitivo":{"motivo":"Cobrar as duas transitividades pela inversão do critério.","palavraCritica":"transitivo direto ... regido de preposição"},"comentario":{"resolucao":"ERRADO. Está invertido: quem exige preposição é o transitivo INDIRETO; quem dispensa é o DIRETO. O nome ajuda a fixar — o complemento chega direto ao verbo, sem intermediário, ou chega indiretamente, pela preposição.","fundamento":"Nomenclatura Gramatical Brasileira — predicação verbal.","macete":"Direto = sem ponte. Indireto = pela ponte da preposição.","erroComum":"Trocar os dois por não associar o nome ao critério.","comoBancaPensa":"Permuta os critérios de duas classificações elementares, contando com a leitura automática."}},"PT-067":{"cognitivo":{"motivo":"Contraexemplo: duas transitividades distintas corretamente identificadas, uma delas com regência que a banca explora.","palavraCritica":"assistiu ao interrogatório"},"comentario":{"resolucao":"CERTO. \"Entregar\" pede dois complementos — entrega-se algo (objeto direto) a alguém (objeto indireto): transitivo direto e indireto. \"Assistir\", no sentido de presenciar, é transitivo indireto e rege a preposição \"a\" — daí \"assistiu AO interrogatório\". No sentido de prestar assistência, seria transitivo direto: \"O médico assistiu o ferido\".","fundamento":"Nomenclatura Gramatical Brasileira e regência do verbo assistir.","macete":"Assistir a algo = ver. Assistir alguém = socorrer. A preposição muda o sentido.","erroComum":"Marcar ERRADO por desconfiar de item que classifica dois verbos de uma vez.","comoBancaPensa":"Apresenta corretamente duas análises, uma delas envolvendo regência que costuma ser cobrada pelo erro."}},"PT-068":{"cognitivo":{"motivo":"Cobrar o objeto direto preposicionado, em que a preposição não decorre da regência.","palavraCritica":"transforma o termo ... em objeto indireto"},"comentario":{"resolucao":"ERRADO. \"Respeitar\" é transitivo direto — respeita-se alguém, não a alguém. A preposição aqui é facultativa, de valor expressivo, e o termo continua sendo OBJETO DIRETO PREPOSICIONADO. A transitividade é propriedade do verbo: não muda porque se acrescentou uma preposição não exigida por ele.","fundamento":"Gramática normativa — objeto direto preposicionado.","macete":"Preposição que o verbo não pede não cria objeto indireto.","erroComum":"Tomar toda preposição como sinal de objeto indireto.","comoBancaPensa":"Usa a presença da preposição como se fosse critério suficiente, ignorando a regência do verbo."}},"PT-069":{"cognitivo":{"motivo":"Contraexemplo: uma enumeração restritiva que corresponde ao que a gramática prevê.","palavraCritica":"hipóteses restritas"},"comentario":{"resolucao":"CERTO. As três hipóteses citadas são as tradicionalmente arroladas. Em \"O réu ofendeu a mim\", a preposição é exigida pelo pronome oblíquo tônico, não pelo verbo — que é transitivo direto. Em \"Bebeu do vinho\", a preposição marca o sentido partitivo: bebeu parte dele, não todo. Somam-se ainda casos de ênfase e de clareza na ordem inversa.","fundamento":"Gramática normativa — hipóteses de objeto direto preposicionado.","macete":"Preposição vinda do pronome, do partitivo ou de 'Deus': objeto direto preposicionado.","erroComum":"Marcar ERRADO por achar que a enumeração restringe demais.","comoBancaPensa":"Apresenta uma lista fechada que o candidato desconfia estar incompleta, mas que corresponde à doutrina."}},"PT-070":{"cognitivo":{"motivo":"Cobrar que a posição não determina a função, e que só há objeto indireto se o verbo o exigir.","palavraCritica":"Toda expressão preposicionada"},"comentario":{"resolucao":"ERRADO. \"Permanecer\", no sentido de ficar em um lugar, não exige complemento: \"na viatura\" é adjunto adverbial de lugar. Só há objeto indireto quando o verbo é transitivo indireto e a preposição decorre da regência. Expressões preposicionadas após o verbo podem ser adjunto adverbial, complemento nominal ou agente da passiva.","fundamento":"Nomenclatura Gramatical Brasileira — objeto indireto x adjunto adverbial.","macete":"O verbo pede? É complemento. Só informa circunstância? É adjunto adverbial.","erroComum":"Classificar pela forma (tem preposição) em vez de pela exigência do verbo.","comoBancaPensa":"Generaliza um critério formal, ignorando que a função depende da regência."}},"PT-071":{"cognitivo":{"motivo":"Cobrar a redundância sintática deliberada, recurso de ênfase.","palavraCritica":"retomar ... o termo deslocado"},"comentario":{"resolucao":"CERTO. O objeto pleonástico repete, por meio de pronome oblíquo átono, um complemento já antecipado na oração. \"O inquérito\" foi deslocado para o início e é retomado por \"o\" junto ao verbo. A redundância é intencional e legítima, não vício de linguagem. Existe também o objeto indireto pleonástico: \"A ele, nada lhe disseram\".","fundamento":"Gramática normativa — objeto direto e indireto pleonásticos.","macete":"Termo antecipado e retomado por pronome junto ao verbo: pleonástico.","erroComum":"Tomar a repetição por erro de redação.","comoBancaPensa":"Cobra uma nomenclatura pouco frequente, testando profundidade de estudo."}},"PT-072":{"cognitivo":{"motivo":"Cobrar uma nomenclatura de menor frequência, que costuma diferenciar candidatos.","palavraCritica":"repete o radical ou a ideia expressa pelo próprio verbo"},"comentario":{"resolucao":"CERTO. O objeto cognato dá complemento a um verbo normalmente intransitivo, retomando sua própria significação — \"viver uma vida\", \"sonhar um sonho\", \"chorar lágrimas amargas\". Costuma vir acompanhado de modificador, que é o que justifica a construção: sem o adjetivo, a frase seria mera redundância.","fundamento":"Gramática normativa — objeto direto cognato ou interno.","macete":"Verbo e objeto da mesma família: objeto cognato.","erroComum":"Tratar a construção como pleonasmo vicioso.","comoBancaPensa":"Cobra termo técnico raro, para separar quem estudou a nomenclatura completa."}},"PT-073":{"cognitivo":{"motivo":"Cobrar a diferença entre complemento (exigido) e adjunto (acessório).","palavraCritica":"não admite ... qualquer termo"},"comentario":{"resolucao":"ERRADO. O verbo intransitivo dispensa COMPLEMENTO, mas admite adjuntos adverbiais à vontade. Em \"A guarnição chegou rapidamente ao local\", \"chegar\" continua intransitivo: \"rapidamente\" é adjunto adverbial de modo e \"ao local\" é adjunto adverbial de lugar. Nenhum dos dois completa o sentido do verbo — apenas o circunstanciam.","fundamento":"Nomenclatura Gramatical Brasileira — verbos intransitivos e adjuntos adverbiais.","macete":"Intransitivo não pede complemento, mas aceita circunstância à vontade.","erroComum":"Concluir a transitividade pela mera presença de termos após o verbo.","comoBancaPensa":"Confunde ausência de complemento com ausência de qualquer termo posposto."}},"PT-074":{"cognitivo":{"motivo":"Cobrar a identificação da função de um complemento longo e não preposicionado.","palavraCritica":"objeto indireto"},"comentario":{"resolucao":"ERRADO. \"Ouvir\" é transitivo direto: ouve-se alguma coisa, sem preposição. O termo é OBJETO DIRETO, cujo núcleo é \"depoimentos\". A preposição que aparece dentro do sintagma — em \"das testemunhas\" — liga-se ao substantivo \"depoimentos\", não ao verbo: ali há adjunto adnominal, e não regência verbal.","fundamento":"Nomenclatura Gramatical Brasileira — objeto direto e adjunto adnominal.","macete":"Preposição interna ao termo não torna o complemento indireto. Olhe o que o verbo pede.","erroComum":"Ver preposição em qualquer ponto do sintagma e concluir objeto indireto.","comoBancaPensa":"Alonga o complemento e insere preposição interna, para embaralhar a leitura da regência."}},"PT-075":{"cognitivo":{"motivo":"Cobrar as duas definições, base da distinção mais cobrada da sintaxe.","palavraCritica":"substantivo abstrato, adjetivo ou advérbio"},"comentario":{"resolucao":"CERTO. O adjunto adnominal caracteriza ou determina um substantivo e pode vir com ou sem preposição. O complemento nominal é sempre preposicionado e integra o sentido de um nome incompleto — que pode ser substantivo abstrato, adjetivo ou advérbio. Essa última possibilidade é a menos lembrada: em \"Agiu favoravelmente ao acordo\", \"ao acordo\" completa o advérbio.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adnominal e complemento nominal.","macete":"Adjunto adnominal só se liga a substantivo. Complemento nominal também completa adjetivo e advérbio.","erroComum":"Ignorar que adjetivo e advérbio admitem complemento nominal.","comoBancaPensa":"Item 'limpo' que estabelece o critério antes das aplicações mais difíceis."}},"PT-076":{"cognitivo":{"motivo":"Cobrar as três classes que admitem complemento nominal.","palavraCritica":"somente a substantivos"},"comentario":{"resolucao":"ERRADO. Adjetivos e advérbios admitem complemento nominal com frequência. Em \"O servidor é leal à instituição\", \"à instituição\" completa o adjetivo \"leal\". Em \"Agiu lealmente à instituição\", completa o advérbio \"lealmente\". Aliás, é justamente esse o critério mais seguro: expressão preposicionada ligada a adjetivo ou advérbio é sempre complemento nominal, sem chance de ser adjunto adnominal.","fundamento":"Nomenclatura Gramatical Brasileira — complemento nominal de substantivo, adjetivo e advérbio.","macete":"Ligado a adjetivo ou advérbio? Complemento nominal, sem dúvida.","erroComum":"Restringir o complemento nominal ao complemento de substantivo.","comoBancaPensa":"Suprime duas das três classes possíveis, deixando só a mais lembrada."}},"PT-077":{"cognitivo":{"motivo":"Contraexemplo: dois absolutos ('nunca', 'sempre') em uma regra que efetivamente não admite exceção.","palavraCritica":"nunca ... sempre"},"comentario":{"resolucao":"CERTO. Substantivo concreto designa ser de existência independente e não precisa de complemento — não há sentido a completar. Assim, em \"a arma do crime\" ou \"o carro do suspeito\", as expressões preposicionadas são adjuntos adnominais. A dúvida entre as duas funções só se instala diante de substantivo ABSTRATO, e é aí que se aplicam os testes de agente e paciente.","fundamento":"Gramática normativa — complemento nominal e substantivos abstratos.","macete":"Substantivo concreto não tem complemento nominal. Só abstrato gera dúvida.","erroComum":"Marcar ERRADO por reflexo diante de 'nunca' e 'sempre'.","comoBancaPensa":"Emprega dois absolutos em regra categórica, punindo quem responde por vocabulário."}},"PT-078":{"cognitivo":{"motivo":"Cobrar a aplicação do critério do substantivo concreto.","palavraCritica":"completar o sentido do substantivo"},"comentario":{"resolucao":"ERRADO. \"Revólver\" é substantivo concreto e tem sentido completo por si — nada há a completar. \"Do acusado\" apenas o especifica, indicando posse: é adjunto adnominal. O item usa o verbo \"completar\" como se bastasse enunciá-lo para que a função existisse.","fundamento":"Gramática normativa — adjunto adnominal ligado a substantivo concreto.","macete":"Ideia de posse junto a substantivo concreto: adjunto adnominal.","erroComum":"Classificar como complemento nominal toda expressão iniciada por 'de'.","comoBancaPensa":"Afirma a função e a justifica com a própria definição, sem testar se o substantivo a comporta."}},"PT-079":{"cognitivo":{"motivo":"Contraexemplo: o critério agente/paciente aplicado corretamente aos dois lados.","palavraCritica":"quem sofre ... quem pratica"},"comentario":{"resolucao":"CERTO. Diante de substantivo abstrato, o teste decisivo é o papel semântico. O foragido não prendeu — foi preso: é paciente, logo complemento nominal. O magistrado não foi decidido — ele decidiu: é agente, logo adjunto adnominal. Note que a mesma preposição \"de\" aparece nos dois, o que mostra que a forma não resolve a questão.","fundamento":"Gramática normativa — critério de agente e paciente na distinção entre adjunto adnominal e complemento nominal.","macete":"Praticou a ação? Adjunto adnominal. Sofreu a ação? Complemento nominal.","erroComum":"Marcar ERRADO por desconfiar de item que classifica duas expressões de modo oposto.","comoBancaPensa":"Aplica corretamente o critério que costuma inverter, checando compreensão do papel semântico."}},"PT-080":{"cognitivo":{"motivo":"Cobrar o mesmo critério com os papéis semânticos invertidos.","palavraCritica":"complemento nominal designa sempre o agente"},"comentario":{"resolucao":"ERRADO. A premissa está invertida: o complemento nominal designa o PACIENTE, e o adjunto adnominal, o agente. Os peritos não convocaram — foram convocados; \"dos peritos\" é, portanto, complemento nominal. Quem convocou é a chefia, e o próprio item entrega isso ao mencioná-la.","fundamento":"Gramática normativa — complemento nominal como paciente e adjunto adnominal como agente.","macete":"Complemento nominal é sempre o alvo da ação, nunca quem a pratica.","erroComum":"Trocar os papéis e classificar o paciente como adjunto adnominal.","comoBancaPensa":"Enuncia uma regra invertida e a aplica coerentemente, o que dá aparência de consistência ao erro."}},"PT-081":{"cognitivo":{"motivo":"Contraexemplo: um absoluto verdadeiro, que fornece o atalho mais seguro da matéria.","palavraCritica":"Qualquer ... sempre"},"comentario":{"resolucao":"CERTO. A regra é categórica e vale como atalho: adjunto adnominal só modifica SUBSTANTIVO. Logo, se o termo preposicionado se liga a um adjetivo, a única função possível é complemento nominal. O mesmo raciocínio se aplica aos advérbios. É o único ponto da matéria em que não é preciso testar agente e paciente.","fundamento":"Nomenclatura Gramatical Brasileira — complemento nominal de adjetivos e advérbios.","macete":"Ligou-se a adjetivo ou advérbio? Complemento nominal, sem análise adicional.","erroComum":"Marcar ERRADO diante de 'qualquer' e 'sempre', sem notar que a regra é mesmo fechada.","comoBancaPensa":"Reúne dois absolutos em regra sem exceção, para punir a resposta por vocabulário."}},"PT-082":{"cognitivo":{"motivo":"Cobrar que o adjunto adnominal pode ou não vir preposicionado.","palavraCritica":"jamais admite preposição"},"comentario":{"resolucao":"ERRADO. O adjunto adnominal admite preposição sem dificuldade: em \"casa de madeira\", \"homem de coragem\" e \"delegacia da capital\", todas as expressões preposicionadas são adjuntos adnominais. É precisamente por ambos poderem ser preposicionados que a distinção entre adjunto adnominal e complemento nominal exige análise, e não simples inspeção da forma.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adnominal preposicionado.","macete":"Preposição não decide nada. Se decidisse, não haveria a dificuldade clássica da matéria.","erroComum":"Adotar a presença de preposição como critério suficiente.","comoBancaPensa":"Oferece um critério formal simples para uma distinção que é semântica."}},"PT-083":{"cognitivo":{"motivo":"Cobrar a definição e o alcance do adjunto adverbial.","palavraCritica":"ou a oração inteira"},"comentario":{"resolucao":"CERTO. A invariabilidade é o traço formal que o distingue do predicativo. Quanto ao alcance, o adjunto adverbial modifica verbo (\"agiu prudentemente\"), adjetivo (\"muito prudente\"), outro advérbio (\"bem prudentemente\") e até a oração toda (\"Infelizmente, o prazo venceu\"), caso em que se costuma chamá-lo de modalizador.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adverbial.","macete":"Invariável e circunstancial. Se varia, não é adjunto adverbial.","erroComum":"Restringir o adjunto adverbial à modificação do verbo.","comoBancaPensa":"Item 'limpo' que fixa o critério formal usado nas comparações seguintes."}},"PT-084":{"cognitivo":{"motivo":"Cobrar a identificação do termo modificado, que decide entre as duas funções.","palavraCritica":"acrescentar informação ao substantivo"},"comentario":{"resolucao":"ERRADO. \"Com lupa\" não caracteriza o veículo — não se trata de um veículo com lupa. A expressão indica o instrumento com que se examinou: liga-se ao verbo e é adjunto adverbial de instrumento. O teste é deslocar o termo: \"Com lupa, a perícia examinou o veículo\" continua coerente, o que confirma o vínculo com o verbo, não com o substantivo.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adverbial de instrumento.","macete":"Dá para deslocar sem quebrar o sentido? Liga-se ao verbo: adjunto adverbial.","erroComum":"Classificar pela proximidade com o substantivo, e não pelo sentido.","comoBancaPensa":"Explora a posição do termo, contando com a análise por vizinhança em vez de por função."}},"PT-085":{"cognitivo":{"motivo":"Contraexemplo: duas circunstâncias distintas corretamente identificadas no mesmo verbo.","palavraCritica":"causa ... modo"},"comentario":{"resolucao":"CERTO. O medo é o motivo que levou à confissão — circunstância de causa, verificável pela pergunta \"por que confessou?\". A ausência de hesitação descreve como a confissão se deu — circunstância de modo, verificável por \"de que maneira confessou?\". O mesmo verbo admite as duas, e a preposição isolada não define a circunstância: o contexto define.","fundamento":"Nomenclatura Gramatical Brasileira — circunstâncias do adjunto adverbial.","macete":"Por que aconteceu? Causa. Como aconteceu? Modo.","erroComum":"Marcar ERRADO por desconfiar de item que classifica duas expressões de uma vez.","comoBancaPensa":"Apresenta corretamente duas circunstâncias vizinhas, checando o uso das perguntas-teste."}},"PT-086":{"cognitivo":{"motivo":"Cobrar a distinção entre causa e modo em construção que admite as duas leituras à primeira vista.","palavraCritica":"maneira como ocorreu"},"comentario":{"resolucao":"ERRADO. A exaustão é o motivo do desmaio, não a maneira dele: trata-se de adjunto adverbial de CAUSA. A pergunta-teste resolve — \"Por que desmaiou?\", \"De exaustão\". Modo responderia a \"como desmaiou?\", e a resposta seria algo como \"subitamente\". A preposição \"de\" introduz várias circunstâncias, o que exige análise do sentido.","fundamento":"Nomenclatura Gramatical Brasileira — adjunto adverbial de causa.","macete":"Causa responde 'por quê'. Modo responde 'de que maneira'.","erroComum":"Classificar como modo toda expressão que descreve o estado em que a ação ocorreu.","comoBancaPensa":"Oferece uma paráfrase enganosa ('a maneira como') para induzir à circunstância errada."}},"PT-087":{"cognitivo":{"motivo":"Cobrar o adjunto adverbial de escopo oracional, cobrado em interpretação e em sintaxe.","palavraCritica":"revelando a avaliação de quem o profere"},"comentario":{"resolucao":"CERTO. Não se afirma que o arquivamento se deu de modo lamentável, mas que o enunciador lamenta o fato. Por isso o termo é chamado modalizador: exprime a atitude do falante diante do que enuncia. O mesmo ocorre com \"felizmente\", \"sinceramente\" e \"evidentemente\" — todos sinalizam subjetividade, o que torna o recurso relevante também em interpretação.","fundamento":"Gramática normativa e linguística textual — adjuntos adverbiais modalizadores.","macete":"Vírgula, começo de frase e opinião do falante: modalizador.","erroComum":"Ler o advérbio como circunstância de modo do verbo.","comoBancaPensa":"Cobra a diferença entre modificar o verbo e modalizar o enunciado inteiro."}},"PT-088":{"cognitivo":{"motivo":"Cobrar que o sufixo não determina a circunstância expressa.","palavraCritica":"invariavelmente ... de modo"},"comentario":{"resolucao":"ERRADO. Os três exemplos do próprio item desmentem a regra: \"provavelmente\" exprime dúvida, \"extremamente\" exprime intensidade e \"diariamente\" exprime tempo. O sufixo -mente forma advérbios de várias circunstâncias; a classificação depende do sentido no contexto, jamais da terminação.","fundamento":"Gramática normativa — classificação semântica dos advérbios.","macete":"Sufixo -mente não é sinônimo de modo. Classifique pelo sentido.","erroComum":"Associar automaticamente a terminação -mente à circunstância de modo.","comoBancaPensa":"Enuncia uma regra falsa e a ilustra com exemplos que a contradizem, apostando que não serão testados."}},"PT-089":{"cognitivo":{"motivo":"Cobrar que a classe gramatical se define no uso, e não isoladamente.","palavraCritica":"conforme o emprego"},"comentario":{"resolucao":"CERTO. No primeiro caso, \"policial\" nomeia um ser e é núcleo do sujeito: substantivo. No segundo, caracteriza \"inquérito\": adjetivo. O fenômeno chama-se derivação imprópria e é largamente cobrado — vale igualmente para \"jovem\", \"brasileiro\" e para adjetivos substantivados, como em \"Os feridos foram socorridos\".","fundamento":"Gramática normativa — derivação imprópria e mudança de classe gramatical.","macete":"Palavra solta não tem classe definida. Classe se decide na frase.","erroComum":"Decorar a classe de cada palavra em vez de analisar o emprego.","comoBancaPensa":"Item correto que cobra método de análise, e não memorização de listas."}},"PT-090":{"cognitivo":{"motivo":"Cobrar a diferença entre classe gramatical e função sintática, e entre artigo e pronome.","palavraCritica":"artigo definido, por determinar o substantivo"},"comentario":{"resolucao":"ERRADO. \"Nosso\" é pronome possessivo — os artigos definidos são apenas o, a, os, as. O item se apoia em uma verdade parcial: a palavra de fato determina o substantivo, e por isso exerce a função sintática de adjunto adnominal. Mas determinar não é ser artigo: classe gramatical é morfologia; adjunto adnominal é sintaxe.","fundamento":"Gramática normativa — classes de palavras e função de adjunto adnominal.","macete":"Artigo definido é só o, a, os, as. O resto que determina é pronome ou numeral.","erroComum":"Confundir a função (adjunto adnominal) com a classe (pronome possessivo).","comoBancaPensa":"Usa uma justificativa sintática verdadeira para sustentar uma classificação morfológica falsa."}},"PT-091":{"cognitivo":{"motivo":"Contraexemplo: dois fenômenos que a banca permuta, aqui definidos corretamente.","palavraCritica":"sem sofrer perda de fonema"},"comentario":{"resolucao":"CERTO. Em \"a + o = ao\", nada se perde: a preposição e o artigo permanecem íntegros — é combinação. Em \"de + o = do\", perde-se o \"e\"; em \"em + esta = nesta\" e \"a + aquele = àquele\", há alteração — são contrações. O critério é exclusivamente fonético, e a lista de combinações é curtíssima: ao, aos, aonde.","fundamento":"Gramática normativa — combinação e contração de preposições.","macete":"Perdeu letra ou som? Contração. Só juntou? Combinação. 'Ao' é o exemplo clássico.","erroComum":"Marcar ERRADO por desconfiar de item que define dois fenômenos de uma vez.","comoBancaPensa":"Define corretamente o par que costuma inverter, checando o domínio do critério fonético."}},"PT-092":{"cognitivo":{"motivo":"Cobrar a aplicação do critério fonético a um caso concreto.","palavraCritica":"se mantêm integralmente"},"comentario":{"resolucao":"ERRADO. \"Pelos\" é contração: a antiga preposição \"per\" perde o \"r\" ao unir-se ao artigo. Só há combinação quando nada se altera, o que ocorre em \"ao\", \"aos\" e \"aonde\". Havendo qualquer supressão ou modificação de som, o fenômeno é contração — como em do, no, dele, nesta, àquela.","fundamento":"Gramática normativa — contração de preposições.","macete":"Se sumiu alguma letra na junção, é contração. 'Pelos' perdeu o r.","erroComum":"Classificar como combinação toda união de preposição com artigo.","comoBancaPensa":"Afirma a integridade das formas justamente no caso em que houve perda fonética."}},"PT-093":{"cognitivo":{"motivo":"Cobrar a locução adjetiva e sua função sintática.","palavraCritica":"exerce ... a função de adjunto adnominal"},"comentario":{"resolucao":"CERTO. A locução adjetiva é formada por preposição mais substantivo e comporta-se como adjetivo, caracterizando um nome — daí exercer a função de adjunto adnominal. Outros exemplos: \"de mãe\" (materno), \"de crime\" (criminal), \"de juiz\" (judicial). Nem toda locução adjetiva tem adjetivo correspondente, mas a função permanece.","fundamento":"Gramática normativa — locução adjetiva e adjunto adnominal.","macete":"Preposição + substantivo com valor de adjetivo: locução adjetiva, função de adjunto adnominal.","erroComum":"Classificar a locução adjetiva como complemento nominal, por vir preposicionada.","comoBancaPensa":"Item correto que articula morfologia e sintaxe no mesmo enunciado."}},"PT-094":{"cognitivo":{"motivo":"Cobrar a separação entre os planos morfológico e sintático, que atravessa toda a matéria.","palavraCritica":"a mesma realidade linguística"},"comentario":{"resolucao":"ERRADO. Não são a mesma coisa, e os rótulos ainda estão invertidos: \"adjetivo\" é classe gramatical, matéria da MORFOLOGIA; \"adjunto adnominal\" é função, matéria da SINTAXE. Além disso, não há correspondência de um para um: um artigo, um numeral ou um pronome possessivo também exercem a função de adjunto adnominal sem serem adjetivos.","fundamento":"Gramática normativa — distinção entre classe gramatical e função sintática.","macete":"Classe é o que a palavra é. Função é o que ela faz na frase.","erroComum":"Tratar classe e função como sinônimos.","comoBancaPensa":"Funde os dois planos de análise e ainda inverte a qual disciplina cada termo pertence."}},"PT-095":{"cognitivo":{"motivo":"Contraexemplo: o par perfeito/imperfeito, que a banca permuta, aqui atribuído corretamente.","palavraCritica":"sem delimitação de término"},"comentario":{"resolucao":"CERTO. O pretérito perfeito marca o fato como concluído e pontual; o imperfeito o apresenta em desenvolvimento, como pano de fundo. É justamente por isso que a narrativa costuma alternar os dois: o imperfeito descreve a cena, o perfeito faz a ação avançar. A conjunção \"enquanto isso\" reforça a simultaneidade entre o fato acabado e o processo em curso.","fundamento":"Gramática normativa — aspecto verbal do pretérito perfeito e do imperfeito.","macete":"Perfeito fecha a ação. Imperfeito deixa ela correndo.","erroComum":"Tratar os dois como equivalentes por ambos indicarem passado.","comoBancaPensa":"Apresenta corretamente o par que costuma inverter, punindo a resposta por formato."}},"PT-096":{"cognitivo":{"motivo":"Cobrar o reconhecimento do mais-que-perfeito simples, forma que a banca confunde com o futuro do pretérito.","palavraCritica":"futuro do pretérito"},"comentario":{"resolucao":"ERRADO. \"Deixara\" é pretérito mais-que-perfeito SIMPLES do indicativo: exprime ação anterior a outra já passada — o suspeito saiu antes de a perícia chegar. O futuro do pretérito seria \"deixaria\". A confusão nasce da semelhança das terminações, mas o sentido é oposto: um marca anterioridade no passado, o outro, hipótese.","fundamento":"Gramática normativa — pretérito mais-que-perfeito simples e futuro do pretérito.","macete":"-ARA é passado do passado. -ARIA é hipótese.","erroComum":"Ler \"deixara\" como forma reduzida de \"deixaria\".","comoBancaPensa":"Troca dois tempos de terminação parecida e sentidos incompatíveis."}},"PT-097":{"cognitivo":{"motivo":"Cobrar a equivalência entre as formas simples e composta do mais-que-perfeito.","palavraCritica":"sem prejuízo do sentido"},"comentario":{"resolucao":"CERTO. O mais-que-perfeito composto forma-se com \"ter\" ou \"haver\" no imperfeito mais o particípio. Equivale à forma simples: \"havia solicitado\" = \"solicitara\". A forma composta predomina na língua falada e a simples soa mais formal, mas ambas exprimem o mesmo — ação anterior a outro fato passado.","fundamento":"Gramática normativa — formas simples e composta do mais-que-perfeito.","macete":"Havia feito = fizera. Mesmo tempo, registros diferentes.","erroComum":"Supor que a forma composta indica tempo diverso da simples.","comoBancaPensa":"Item correto que cobra a equivalência, e não apenas o reconhecimento."}},"PT-098":{"cognitivo":{"motivo":"Cobrar o valor durativo do pretérito perfeito composto, que se prolonga até o presente.","palavraCritica":"uma única vez ... inteiramente concluído"},"comentario":{"resolucao":"ERRADO. O pretérito perfeito COMPOSTO exprime justamente o contrário: ação ou processo que se repete ou se prolonga do passado até o presente, e que pode continuar. \"Têm caído\" indica queda continuada, não fato único e encerrado. Quem exprime fato único e concluído é o pretérito perfeito simples — \"caíram\".","fundamento":"Gramática normativa — aspecto do pretérito perfeito composto.","macete":"Tenho feito = venho fazendo, e continua. Fiz = acabou.","erroComum":"Igualar o perfeito composto ao perfeito simples por ambos serem 'perfeitos'.","comoBancaPensa":"Atribui ao composto o valor do simples, aproveitando a semelhança do nome."}},"PT-099":{"cognitivo":{"motivo":"Cobrar o valor modal do subjuntivo em oração concessiva.","palavraCritica":"possibilidade admitida"},"comentario":{"resolucao":"CERTO. O subjuntivo é o modo da incerteza, da hipótese e da concessão. A locução \"ainda que\" é concessiva e exige subjuntivo: o enunciador admite o fato sem afirmá-lo como certo. Se estivesse no indicativo — \"indicam\" —, o fato seria apresentado como real e a construção exigiria outro conectivo.","fundamento":"Gramática normativa — modo subjuntivo em orações concessivas.","macete":"Ainda que, embora, conquanto: puxam subjuntivo.","erroComum":"Confundir o subjuntivo com tempo verbal, e não com modo.","comoBancaPensa":"Item correto que liga modo verbal ao conectivo que o exige."}},"PT-100":{"cognitivo":{"motivo":"Contraexemplo: identificação correta do futuro do pretérito, tempo que a banca troca pelo mais-que-perfeito.","palavraCritica":"hipótese não verificada"},"comentario":{"resolucao":"CERTO. O período condicional típico combina imperfeito do subjuntivo na hipótese (\"houvesse\") com futuro do pretérito na consequência (\"sairiam\"). O futuro do pretérito exprime o que aconteceria caso a condição se realizasse — e o fato de ela não se realizar é o que caracteriza a hipótese. É também o tempo do desejo cortês e da notícia não confirmada.","fundamento":"Gramática normativa — futuro do pretérito e correlação em período condicional.","macete":"SE + imperfeito do subjuntivo, então futuro do pretérito. Houvesse/sairiam.","erroComum":"Marcar ERRADO por desconfiar da nomenclatura 'futuro do pretérito'.","comoBancaPensa":"Nomeia corretamente o tempo que costuma confundir com o mais-que-perfeito."}},"PT-101":{"cognitivo":{"motivo":"Cobrar que há mais de uma correlação condicional válida.","palavraCritica":"obrigatoriamente"},"comentario":{"resolucao":"ERRADO. A construção está correta. Há duas correlações condicionais consagradas: futuro do subjuntivo com futuro do presente — \"se cumprir, seguirá\", que expressa condição realizável; e imperfeito do subjuntivo com futuro do pretérito — \"se cumprisse, seguiria\", que expressa hipótese improvável ou irreal. O item elege uma como única e reprova a outra.","fundamento":"Gramática normativa — correlação de tempos em período condicional.","macete":"Cumprir/seguirá = possível. Cumprisse/seguiria = hipotético.","erroComum":"Supor que toda condicional é hipotética e pede imperfeito.","comoBancaPensa":"Transforma uma das correlações possíveis em exigência única."}},"PT-102":{"cognitivo":{"motivo":"Contraexemplo: análise correta do SE apassivador, com o teste de conversão.","palavraCritica":"possibilidade de conversão"},"comentario":{"resolucao":"CERTO. \"Analisar\" é transitivo direto, logo o SE é partícula apassivadora e o termo seguinte é sujeito — por isso o verbo concorda no plural. O teste decisivo é o do item: se a frase admite conversão para a passiva analítica com \"ser + particípio\", é voz passiva sintética. Se não admitisse, o SE seria índice de indeterminação do sujeito.","fundamento":"Gramática normativa — voz passiva sintética e teste de conversão.","macete":"Converteu para 'foi/foram + particípio'? É passiva sintética, e o verbo concorda.","erroComum":"Marcar ERRADO por desconfiar de item que já traz a análise pronta.","comoBancaPensa":"Apresenta corretamente a análise que costuma distorcer, com o teste explícito."}},"PT-103":{"cognitivo":{"motivo":"Cobrar a função de agente da passiva, distinta da de sujeito.","palavraCritica":"função de sujeito"},"comentario":{"resolucao":"ERRADO. \"Pelo diretor\" é AGENTE DA PASSIVA — quem pratica a ação, mas não é o sujeito. O sujeito é \"O relatório\", que sofre a ação e com quem o verbo concorda. Na voz passiva, quem pratica e quem é sujeito se separam: é exatamente essa dissociação que a define. Na conversão para a ativa, o agente da passiva vira sujeito: \"O diretor assinou o relatório\".","fundamento":"Gramática normativa — agente da passiva e sujeito paciente.","macete":"Na passiva, o sujeito sofre. Quem faz é o agente da passiva.","erroComum":"Igualar 'quem pratica a ação' a 'sujeito'.","comoBancaPensa":"Usa a noção intuitiva de sujeito como agente, que a voz passiva desmente."}},"PT-104":{"cognitivo":{"motivo":"Cobrar a formação do imperativo, que a banca cobra pela derivação.","palavraCritica":"sem o -s final"},"comentario":{"resolucao":"CERTO. É a regra de formação: \"tu cantas\" gera \"canta tu\" (afirmativo, sem o -s); e o negativo vem do subjuntivo — \"não cantes tu\". As demais pessoas do imperativo, afirmativo e negativo, vêm todas do presente do subjuntivo. Daí a assimetria que gera erro corrente: \"faça\" e \"não faça\", mas \"faz tu\" e \"não faças tu\".","fundamento":"Gramática normativa — formação do modo imperativo.","macete":"Afirmativo de tu/vós: tira o -s do indicativo. Todo o resto vem do subjuntivo.","erroComum":"Misturar as formas de tratamento e produzir 'não faz' em vez de 'não faças'.","comoBancaPensa":"Item correto sobre uma formação que quase ninguém revisa."}},"PT-105":{"cognitivo":{"motivo":"Contraexemplo: rol fechado e categórico que corresponde à gramática.","palavraCritica":"apenas três"},"comentario":{"resolucao":"CERTO. São exatamente essas três, chamadas nominais porque podem exercer funções próprias de nomes: o infinitivo aproxima-se do substantivo, o gerúndio e o particípio, do advérbio e do adjetivo. Não indicam tempo por si sós, o que as distingue das formas finitas. O rol é fechado — não há quarta forma nominal.","fundamento":"Nomenclatura Gramatical Brasileira — formas nominais do verbo.","macete":"Infinitivo, gerúndio e particípio. Só essas três.","erroComum":"Marcar ERRADO por reflexo diante de 'apenas'.","comoBancaPensa":"Numeral fechado em rol que é mesmo taxativo."}},"PT-106":{"cognitivo":{"motivo":"Cobrar os valores secundários do presente, que a restrição nega.","palavraCritica":"somente ... incorreto"},"comentario":{"resolucao":"ERRADO. O presente tem vários empregos além do momentâneo: futuro próximo (\"a prova acontece em novembro\"), verdade permanente ou atemporal (\"a água ferve a 100 °C\"), fato habitual (\"o plantão começa às sete\") e presente histórico, que narra o passado com vivacidade (\"em 1988, promulga-se a Constituição\"). Todos são legítimos na norma-padrão.","fundamento":"Gramática normativa — valores do presente do indicativo.","macete":"O presente serve para agora, sempre, de hábito, para o futuro próximo e para narrar o passado.","erroComum":"Restringir cada tempo verbal a um único valor semântico.","comoBancaPensa":"Reduz um tempo de múltiplos empregos ao seu valor mais óbvio."}},"PT-107":{"cognitivo":{"motivo":"Contraexemplo: classificação e substituição corretas de conectivo, no formato em que a banca troca a relação.","palavraCritica":"sem alteração do sentido"},"comentario":{"resolucao":"CERTO. \"No entanto\", \"contudo\", \"todavia\", \"entretanto\", \"porém\" e \"mas\" formam o grupo das adversativas: todas marcam oposição ou contraste. A substituição entre elas é livre quanto ao sentido — muda só o registro e a pontuação, já que \"mas\" costuma vir sem ponto e vírgula antes.","fundamento":"Gramática normativa — conjunções coordenativas adversativas.","macete":"Mas, porém, contudo, todavia, entretanto, no entanto: todas opõem.","erroComum":"Marcar ERRADO por desconfiar de item que autoriza substituição.","comoBancaPensa":"Classifica corretamente um conectivo cuja relação costuma distorcer."}},"PT-108":{"cognitivo":{"motivo":"Cobrar a diferença entre conclusão e oposição, com dois conectivos de forma parecida.","palavraCritica":"preservaria a relação lógica"},"comentario":{"resolucao":"ERRADO. \"Portanto\" é CONCLUSIVO: a segunda oração decorre da primeira. \"Entretanto\" é ADVERSATIVO: a segunda contraria a expectativa da primeira. As relações são opostas, e a troca inverteria o sentido do período. A semelhança sonora entre os dois é justamente o que a banca explora.","fundamento":"Gramática normativa — conjunções conclusivas e adversativas.","macete":"PorTANTO conclui. EnTREtanto opõe. Sons parecidos, sentidos contrários.","erroComum":"Trocar os dois por semelhança fonética.","comoBancaPensa":"Propõe substituição entre conectivos parecidos na forma e opostos na função."}},"PT-109":{"cognitivo":{"motivo":"Cobrar o valor da concessão, frequentemente confundido com o da condição.","palavraCritica":"não impede"},"comentario":{"resolucao":"CERTO. A concessão admite um obstáculo e afirma que ele não impede o fato principal — é a lógica do \"apesar de\". Integram o grupo embora, ainda que, conquanto, se bem que, posto que e mesmo que, todas exigindo subjuntivo. Não confundir com a condicional, que subordina a realização do principal ao cumprimento da condição.","fundamento":"Gramática normativa — orações subordinadas adverbiais concessivas.","macete":"Concessiva é obstáculo que não impede. Condicional é requisito que precisa acontecer.","erroComum":"Confundir concessiva com condicional.","comoBancaPensa":"Item correto que define a relação antes de cobrá-la nas trocas."}},"PT-110":{"cognitivo":{"motivo":"Cobrar a distinção entre concessão e condição na aplicação.","palavraCritica":"relação de condição ... dependia"},"comentario":{"resolucao":"ERRADO. \"Embora\" é concessiva: a expiração do prazo era obstáculo esperado ao conhecimento do recurso, e ainda assim ele foi conhecido. Não há dependência — há contraste com a expectativa. A relação de condição seria expressa por \"se\", \"caso\", \"contanto que\", e implicaria que um fato só ocorre se o outro ocorrer.","fundamento":"Gramática normativa — orações concessivas e condicionais.","macete":"Embora = apesar de. Se = só acontece caso.","erroComum":"Ler qualquer subordinada adverbial como condicional.","comoBancaPensa":"Atribui a uma concessiva a lógica de dependência própria da condicional."}},"PT-111":{"cognitivo":{"motivo":"Cobrar o duplo valor de 'pois', decidido pela posição.","palavraCritica":"posposta ao verbo"},"comentario":{"resolucao":"CERTO. A posição decide: \"Estude, pois a prova se aproxima\" é explicativo — a segunda oração justifica a primeira. \"A prova se aproxima; estude, pois\" é conclusivo — equivale a portanto. É um dos poucos casos em que a mesma palavra muda de classificação pela colocação na frase.","fundamento":"Gramática normativa — valores da conjunção 'pois'.","macete":"Pois antes do verbo explica; pois depois do verbo conclui.","erroComum":"Classificar 'pois' sempre como explicativo.","comoBancaPensa":"Item correto sobre um conectivo de comportamento duplo, pouco revisado."}},"PT-112":{"cognitivo":{"motivo":"Contraexemplo: classificação correta de conectivo que a banca costuma rotular como comparativo.","palavraCritica":"acordo entre o que se declara e uma norma"},"comentario":{"resolucao":"CERTO. A conformativa exprime conformidade com um padrão — regimento, lei, previsão. Integram o grupo conforme, segundo, consoante e como (neste sentido). A confusão frequente é com a comparativa, porque \"como\" serve às duas: em \"agiu como manda a lei\" há conformidade; em \"agiu como um profissional\" há comparação.","fundamento":"Gramática normativa — orações subordinadas adverbiais conformativas.","macete":"Conforme, segundo, consoante: de acordo com. É conformativa.","erroComum":"Classificar toda ocorrência de 'como' como comparativa.","comoBancaPensa":"Nomeia corretamente uma relação de menor frequência, que o candidato tende a rejeitar."}},"PT-113":{"cognitivo":{"motivo":"Cobrar a relação de proporcionalidade, que a banca reduz a tempo.","palavraCritica":"apenas a simultaneidade"},"comentario":{"resolucao":"ERRADO. \"À medida que\" é locução conjuntiva PROPORCIONAL: os fatos não apenas coincidem no tempo, mas variam juntos — quanto mais laudos chegavam, mais as diligências avançavam. Há simultaneidade, é verdade, mas o traço definidor é a proporção. Cuidado com a forma \"à medida que\": \"na medida em que\" tem valor causal, e a troca entre as duas é erro corrente.","fundamento":"Gramática normativa — orações subordinadas adverbiais proporcionais.","macete":"À medida que = proporção. Na medida em que = causa.","erroComum":"Reduzir a proporcional a temporal por haver simultaneidade.","comoBancaPensa":"Oferece a relação parcialmente presente ('tempo') e nega a definidora, com 'apenas'."}},"PT-114":{"cognitivo":{"motivo":"Cobrar a consecutiva e o intensificador que a anuncia.","palavraCritica":"intensidade"},"comentario":{"resolucao":"CERTO. A consecutiva exprime consequência de uma intensidade, e vem anunciada por um intensificador na principal — tanto, tal, tão, tamanho. Sem ele, a oração com \"que\" seria de outra natureza. A diferença para a causal é a direção: a causal dá o motivo (\"precisou de reforço porque o volume era grande\"), a consecutiva dá o efeito.","fundamento":"Gramática normativa — orações subordinadas adverbiais consecutivas.","macete":"Tão/tanto/tal/tamanho + que: consecutiva.","erroComum":"Confundir consecutiva com causal por ambas ligarem causa e efeito.","comoBancaPensa":"Item correto que exige localizar o intensificador na principal."}},"PT-115":{"cognitivo":{"motivo":"Contraexemplo: rol de cinco que corresponde à classificação tradicional.","palavraCritica":"cinco categorias"},"comentario":{"resolucao":"CERTO. São essas cinco na classificação tradicional. Aditivas somam (e, nem, mas também); adversativas opõem (mas, porém); alternativas excluem ou alternam (ou, ora... ora); conclusivas concluem (logo, portanto); explicativas justificam (pois, porque, que). Não há sexta categoria de coordenativa — condicionais, concessivas e causais são subordinativas.","fundamento":"Nomenclatura Gramatical Brasileira — conjunções coordenativas.","macete":"Coordenativas: somam, opõem, alternam, concluem, explicam. Cinco.","erroComum":"Incluir condicionais ou concessivas entre as coordenativas.","comoBancaPensa":"Rol fechado que o candidato tende a considerar incompleto."}},"PT-116":{"cognitivo":{"motivo":"Cobrar o valor adversativo que o 'e' assume em certos contextos.","palavraCritica":"exclusivamente ... nenhum contexto"},"comentario":{"resolucao":"ERRADO. O \"e\" assume valor adversativo quando liga ideias contrastantes: \"Estudou muito e não passou\" equivale a \"mas não passou\". O contexto, e não a conjunção isoladamente, determina a relação — princípio que vale para vários conectivos. É recorte clássico em prova de interpretação, porque exige ler o sentido, não a etiqueta.","fundamento":"Gramática normativa — valores contextuais das conjunções coordenativas.","macete":"'Estudou e não passou' = 'estudou MAS não passou'. O 'e' pode opor.","erroComum":"Classificar conectivos apenas pela lista, sem checar o sentido.","comoBancaPensa":"Fixa em um único valor um conectivo cujo sentido depende do contexto."}},"PT-117":{"cognitivo":{"motivo":"Cobrar a distinção restritiva/explicativa, que decide a pontuação e o sentido.","palavraCritica":"explicativa ... vírgulas"},"comentario":{"resolucao":"ERRADO. A oração é RESTRITIVA: delimita quais servidores receberão o certificado — apenas os que concluíram o curso. Restritiva não admite vírgula. Se fosse explicativa, com vírgulas, o sentido mudaria por completo: todos os servidores teriam concluído o curso e todos receberiam o certificado. A vírgula, aqui, não é detalhe de estilo — altera quem tem direito.","fundamento":"Gramática normativa — orações subordinadas adjetivas restritivas e explicativas.","macete":"Sem vírgula restringe (só alguns). Com vírgula explica (todos).","erroComum":"Tratar a vírgula na adjetiva como opcional.","comoBancaPensa":"Inverte a classificação para justificar uma pontuação que mudaria o sentido do enunciado."}},"PT-118":{"cognitivo":{"motivo":"Cobrar a obrigatoriedade do par de vírgulas na explicativa intercalada.","palavraCritica":"as duas vírgulas"},"comentario":{"resolucao":"CERTO. A explicativa acrescenta informação sobre um ser já determinado — há um só laudo pericial em questão, e a oração apenas informa quando foi concluído. Sendo intercalada, exige as DUAS vírgulas: usar só uma é erro de pontuação frequente e grave, porque separa indevidamente termos que se ligam.","fundamento":"Gramática normativa — pontuação da oração adjetiva explicativa.","macete":"Intercalou? Abre e fecha vírgula. Nunca só uma.","erroComum":"Esquecer a vírgula de fechamento da intercalada.","comoBancaPensa":"Item correto que cobra o par de vírgulas, e não apenas a classificação."}},"PT-119":{"cognitivo":{"motivo":"Cobrar a identificação da subordinada substantiva subjetiva.","palavraCritica":"objeto direto"},"comentario":{"resolucao":"ERRADO. A oração é SUBJETIVA — exerce a função de sujeito. O teste é substituir por \"isso\": \"Isso é necessário\", em que \"isso\" é claramente sujeito. A principal, aqui, é oração sem sujeito próprio: \"é necessário\" é predicado nominal cujo sujeito é a oração inteira. Objeto direto exigiria verbo transitivo direto, que não há.","fundamento":"Gramática normativa — orações subordinadas substantivas subjetivas.","macete":"Troque por ISSO. Se virar sujeito, a oração é subjetiva.","erroComum":"Classificar toda substantiva iniciada por 'que' como objetiva direta.","comoBancaPensa":"Atribui a função mais comum das substantivas a um caso que é de sujeito."}},"PT-120":{"cognitivo":{"motivo":"Contraexemplo: rol de seis, taxativo, que o candidato tende a achar incompleto.","palavraCritica":"seis classificações"},"comentario":{"resolucao":"CERTO. São essas seis, e a lógica é direta: cada uma corresponde a uma função que um substantivo exerceria na oração simples — sujeito, objeto direto, objeto indireto, complemento nominal, predicativo e aposto. Quem domina os termos da oração simples classifica as substantivas sem decorar lista.","fundamento":"Nomenclatura Gramatical Brasileira — orações subordinadas substantivas.","macete":"As substantivas repetem as funções do substantivo. Seis funções, seis orações.","erroComum":"Esquecer a apositiva ou a predicativa, as menos frequentes.","comoBancaPensa":"Rol fechado cuja extensão gera desconfiança."}},"PT-121":{"cognitivo":{"motivo":"Cobrar o conceito de oração reduzida e sua conversão em desenvolvida.","palavraCritica":"sem conectivo"},"comentario":{"resolucao":"CERTO. Reduzida é a que traz o verbo em infinitivo, gerúndio ou particípio e dispensa conjunção. Classifica-se pelo sentido, convertendo-a mentalmente em desenvolvida: aqui, \"Concluída a perícia\" equivale a \"Depois que a perícia foi concluída\", logo é reduzida de particípio com valor temporal. A ausência de conectivo é o que obriga o candidato a recuperar a relação pelo contexto.","fundamento":"Gramática normativa — orações reduzidas de infinitivo, gerúndio e particípio.","macete":"Sem conjunção e com forma nominal? Reduzida. Desenvolva para classificar.","erroComum":"Não reconhecer subordinação quando falta o conectivo.","comoBancaPensa":"Item correto que ensina o procedimento de conversão."}},"PT-122":{"cognitivo":{"motivo":"Contraexemplo: o critério que distingue os dois 'que', apresentado corretamente.","palavraCritica":"sem retomar termo algum"},"comentario":{"resolucao":"CERTO. É o critério decisivo. Em \"o laudo QUE chegou\", o \"que\" retoma \"laudo\" e pode ser substituído por \"o qual\" — é relativo, e a oração é adjetiva. Em \"Afirmo QUE o laudo chegou\", o \"que\" não retoma nada e não admite \"o qual\" — é conjunção integrante, e a oração é substantiva. O teste da substituição por \"o qual\" resolve praticamente todos os casos.","fundamento":"Gramática normativa — pronome relativo e conjunção integrante.","macete":"Cabe 'o qual'? Relativo, adjetiva. Não cabe? Integrante, substantiva.","erroComum":"Classificar a oração pelo conectivo, sem testar se há antecedente.","comoBancaPensa":"Apresenta corretamente a distinção que sustenta metade da análise do período composto."}},"PT-123":{"cognitivo":{"motivo":"Contraexemplo: nomenclatura correta, num par (sindética/assindética) que a banca troca.","palavraCritica":"sem conjunção"},"comentario":{"resolucao":"CERTO. Assindética vem de \"a-\" (sem) mais \"síndeto\" (conjunção): orações coordenadas justapostas, separadas apenas por vírgula. As sindéticas, ao contrário, vêm com conjunção e recebem a classificação dela — aditiva, adversativa, alternativa, conclusiva ou explicativa. A etimologia resolve a memorização.","fundamento":"Gramática normativa — orações coordenadas sindéticas e assindéticas.","macete":"A- de ausência: assindética é sem conjunção.","erroComum":"Trocar os dois termos por não decompor a palavra.","comoBancaPensa":"Nomeia corretamente o membro do par que costuma inverter."}},"PT-124":{"cognitivo":{"motivo":"Cobrar que a posição não define a oração principal.","palavraCritica":"sempre ... nunca"},"comentario":{"resolucao":"ERRADO. A principal define-se pela função — é a que tem a subordinada como termo dependente —, não pela posição. Em \"Quando o prazo terminar, o processo será arquivado\", a principal é a segunda. E ela pode vir interrompida: em \"O servidor que assinou o termo compareceu\", a subordinada adjetiva está encravada no meio da principal.","fundamento":"Gramática normativa — período composto por subordinação.","macete":"Principal não é a primeira: é a que manda. Pode até vir partida ao meio.","erroComum":"Identificar a principal pela ordem em que aparece.","comoBancaPensa":"Converte uma tendência de ordem em regra fixa, com dois absolutos."}},"PT-125":{"cognitivo":{"motivo":"Contraexemplo: regra categórica de crase que não comporta exceção.","palavraCritica":"não antecede formas verbais"},"comentario":{"resolucao":"CERTO. A crase é a fusão da preposição \"a\" com o artigo \"a\". Como o artigo não acompanha verbo, não há o que fundir: escreve-se \"começou a ganhar corpo\", \"disposto a colaborar\". A regra é absoluta e serve de atalho seguro — vendo verbo depois do \"a\", descarte o acento sem hesitar.","fundamento":"Gramática normativa — casos em que não ocorre crase.","macete":"Depois de 'a' veio verbo? Sem acento, sempre.","erroComum":"Marcar ERRADO por reflexo diante da negativa categórica.","comoBancaPensa":"Regra sem exceção enunciada de forma absoluta, o que gera desconfiança indevida."}},"PT-126":{"cognitivo":{"motivo":"Cobrar os dois elementos que produzem a crase: regência e artigo.","palavraCritica":"fusão"},"comentario":{"resolucao":"CERTO. A crase exige os dois componentes. \"Submeter-se\" rege a preposição \"a\"; \"regras\" admite o artigo \"as\". A + as = às. Faltando qualquer um dos dois, não há acento — é por isso que a análise de crase começa sempre pela regência do termo anterior, e não pela palavra que vem depois do \"a\".","fundamento":"Gramática normativa — formação da crase.","macete":"Crase = preposição exigida + artigo aceito. Faltou um, não tem acento.","erroComum":"Marcar ERRADO por desconfiar de item que explica a própria regra.","comoBancaPensa":"Descreve corretamente o mecanismo, num tema em que o candidato espera pegadinha."}},"PT-127":{"cognitivo":{"motivo":"Cobrar que a crase pressupõe termo feminino, ainda que haja preposição.","palavraCritica":"exige-se o emprego do acento grave"},"comentario":{"resolucao":"ERRADO. Há preposição, sim, mas \"setor\" é masculino: a fusão que ocorre é com o artigo masculino, resultando em \"ao setor\" — combinação, não crase. O acento grave marca a fusão de \"a\" preposição com \"a\" artigo feminino. Diante de palavra masculina, o correto é \"ao\", sem acento grave. A exceção conhecida é \"à moda de\" subentendido.","fundamento":"Gramática normativa — crase e gênero do termo regido.","macete":"Masculino leva AO. Crase é coisa de palavra feminina.","erroComum":"Concluir pela crase só porque o verbo exige preposição.","comoBancaPensa":"Apresenta metade do requisito (a preposição) como se bastasse."}},"PT-128":{"cognitivo":{"motivo":"Cobrar os três casos de crase facultativa, rol fechado e muito cobrado.","palavraCritica":"facultativo"},"comentario":{"resolucao":"CERTO. São exatamente esses três. A facultatividade decorre de o artigo ser opcional nesses contextos: pode-se dizer \"Refiro-me a Maria\" ou \"à Maria\"; \"Entreguei a minha chefe\" ou \"à minha chefe\"; \"Foi até a porta\" ou \"até à porta\". Sendo facultativo, nenhuma das formas pode ser apontada como erro — e é aí que a banca arma o item.","fundamento":"Gramática normativa — casos de crase facultativa.","macete":"Nome de mulher, possessivo feminino e 'até': tanto faz.","erroComum":"Apontar como erro o que a norma admite nas duas formas.","comoBancaPensa":"Item de rol fechado cuja armadilha correlata é declarar obrigatório o que é facultativo."}},"PT-129":{"cognitivo":{"motivo":"Cobrar a crase nas locuções, que independe de regência.","palavraCritica":"ainda que não haja termo regente"},"comentario":{"resolucao":"CERTO. É regra própria: nas locuções femininas o acento é obrigatório por convenção, inclusive para desfazer ambiguidade com o masculino correspondente — compare \"à noite\" (locução) com \"a noite\" (sujeito). Vale para às claras, às escondidas, à vontade, à risca, à direita. Note que \"à noite\" leva acento mesmo sem verbo que exija preposição.","fundamento":"Gramática normativa — crase em locuções adverbiais femininas.","macete":"Locução feminina leva acento por convenção, não por regência.","erroComum":"Procurar o verbo regente e concluir que não há crase.","comoBancaPensa":"Item correto sobre a regra que foge ao mecanismo geral da crase."}},"PT-130":{"cognitivo":{"motivo":"Cobrar que a maioria dos pronomes rejeita o artigo e, portanto, a crase.","palavraCritica":"qualquer pronome feminino"},"comentario":{"resolucao":"ERRADO. Pronomes pessoais e demonstrativos não admitem artigo, logo não há crase: \"a ela\", \"a esta\", \"a essa\". Há exceções pontuais — \"àquela\", \"àquele\", \"àquilo\", em que o \"a\" preposição se funde com a vogal inicial do demonstrativo; e os pronomes possessivos, de crase facultativa. Generalizar para \"qualquer pronome\" é o erro.","fundamento":"Gramática normativa — crase diante de pronomes.","macete":"A ela, a esta, a essa: sem acento. Àquela e àquilo: com.","erroComum":"Acentuar diante de pronome pessoal por ser feminino.","comoBancaPensa":"Estende a 'qualquer pronome' uma regra que vale só para alguns."}},"PT-131":{"cognitivo":{"motivo":"Cobrar a distinção entre tempo futuro e tempo passado no emprego da crase.","palavraCritica":"expressão de tempo feminina"},"comentario":{"resolucao":"ERRADO. O critério não é o gênero, e sim a direção temporal. Indicando tempo FUTURO, não há crase: \"daqui a duas semanas\", \"daqui a pouco\". Indicando tempo PASSADO, usa-se \"há\": \"há duas semanas\". O acento grave em expressões temporais aparece em outros contextos, como \"às 14 horas\" e \"à noite\", que são locuções.","fundamento":"Gramática normativa — 'a' e 'há' em expressões de tempo.","macete":"Futuro é 'a'. Passado é 'há'. Daqui a pouco / há muito tempo.","erroComum":"Acentuar por ser expressão feminina, sem checar a direção temporal.","comoBancaPensa":"Oferece critério irrelevante (o gênero) para decidir um caso que se resolve pelo tempo."}},"PT-132":{"cognitivo":{"motivo":"Cobrar a principal palavra atrativa — a conjunção subordinativa.","palavraCritica":"atrai"},"comentario":{"resolucao":"CERTO. Conjunção subordinativa é palavra atrativa e obriga a próclise: \"quando se instaurou\", nunca \"quando instaurou-se\". Somam-se às atrativas as palavras negativas, os advérbios sem pausa, os pronomes relativos, indefinidos e interrogativos, e as orações exclamativas e optativas.","fundamento":"Gramática normativa — colocação pronominal e palavras atrativas.","macete":"Oração subordinada puxa o pronome para antes do verbo.","erroComum":"Usar ênclise depois de conjunção subordinativa.","comoBancaPensa":"Item de regra fixa, muito cobrado em reescritura de trechos."}},"PT-133":{"cognitivo":{"motivo":"Cobrar a vedação da próclise em início de período na norma-padrão.","palavraCritica":"desde que o verbo esteja no presente"},"comentario":{"resolucao":"ERRADO. A norma-padrão não admite pronome oblíquo átono iniciando período: o correto é \"Parece-me que o prazo expirou\". A condição inventada — presente do indicativo — não existe em regra alguma. A construção com próclise inicial é corrente na fala e aceita na variedade coloquial, mas reprovada na escrita formal.","fundamento":"Gramática normativa — vedação da próclise em início de período.","macete":"Não comece frase com me, te, se, lhe, o, a.","erroComum":"Transpor para a escrita formal um uso corrente na fala.","comoBancaPensa":"Cria uma condição de exceção para tornar aceitável o que a norma rejeita."}},"PT-134":{"cognitivo":{"motivo":"Cobrar as duas condições da mesóclise: o tempo verbal e a ausência de atrativo.","palavraCritica":"desde que não haja palavra atrativa"},"comentario":{"resolucao":"CERTO. \"Far-se-á a perícia\" e \"far-se-ia a perícia\" exemplificam os dois tempos. Mas havendo palavra atrativa, a próclise prevalece: \"não se fará a perícia\", jamais \"não far-se-á\". A mesóclise é o único caso em que o pronome se encaixa no meio da forma verbal, entre o radical e a desinência.","fundamento":"Gramática normativa — mesóclise.","macete":"Futuro sem atrativo: mesóclise. Com atrativo: próclise vence.","erroComum":"Usar mesóclise mesmo diante de palavra negativa.","comoBancaPensa":"Item correto que cobra a ressalva, e não apenas a regra geral."}},"PT-135":{"cognitivo":{"motivo":"Contraexemplo: colocação correta com palavra atrativa negativa.","palavraCritica":"exerce atração"},"comentario":{"resolucao":"CERTO. Palavras de sentido negativo — não, nada, ninguém, nunca, jamais, nenhum — atraem o pronome. \"Nada se apurou\" está correto; \"Nada apurou-se\" contraria a norma. Vale notar que a atração cessa se houver pausa entre a palavra negativa e o verbo.","fundamento":"Gramática normativa — palavras atrativas de sentido negativo.","macete":"Negativa perto do verbo puxa o pronome para antes.","erroComum":"Marcar ERRADO por desconfiar de item que valida a construção.","comoBancaPensa":"Confirma uma colocação correta, num tema em que o candidato espera achar erro."}},"PT-136":{"cognitivo":{"motivo":"Cobrar que a posposição do sujeito não altera a concordância.","palavraCritica":"ainda que este venha posposto"},"comentario":{"resolucao":"CERTO. A ordem inversa não dispensa a concordância: o verbo continua a concordar com o sujeito, esteja ele antes ou depois. \"Chegaram os documentos\" está correto; \"Chegou os documentos\" não. O erro é frequente porque a proximidade de um termo singular antes do verbo induz à concordância errada.","fundamento":"Gramática normativa — concordância verbal com sujeito posposto.","macete":"Ache o sujeito, não o que está mais perto do verbo.","erroComum":"Concordar com o termo imediatamente anterior ao verbo.","comoBancaPensa":"Valida uma construção correta em ordem inversa, que soa estranha ao ouvido."}},"PT-137":{"cognitivo":{"motivo":"Cobrar a facultatividade da concordância com expressões partitivas.","palavraCritica":"obrigatoriamente ... incorreta"},"comentario":{"resolucao":"ERRADO. A concordância é FACULTATIVA: \"A maioria dos servidores compareceu\" e \"A maioria dos servidores compareceram\" são ambas corretas. No primeiro caso concorda-se com o núcleo partitivo; no segundo, com o especificador plural, por concordância atrativa ou ideológica. O mesmo vale para grande parte de, metade de, uma porção de.","fundamento":"Gramática normativa — concordância com expressões partitivas.","macete":"A maioria compareceu / compareceram: as duas valem.","erroComum":"Reprovar como erro a forma que a norma admite.","comoBancaPensa":"Transforma uma facultatividade em obrigação e condena a alternativa válida."}},"PT-138":{"cognitivo":{"motivo":"Cobrar a transmissão da impessoalidade ao auxiliar da locução.","palavraCritica":"auxiliar concorda"},"comentario":{"resolucao":"ERRADO. \"Haver\" existencial é impessoal e não tem sujeito; \"outras providências\" é objeto direto, não sujeito. A impessoalidade transmite-se ao auxiliar, de modo que o correto é \"DEVE haver outras providências\". Trata-se de erro muito frequente justamente por soar natural na fala.","fundamento":"Gramática normativa — impessoalidade do verbo haver em locuções verbais.","macete":"Deve haver, pode haver, vai haver. Sempre no singular.","erroComum":"Flexionar o auxiliar pelo termo que parece sujeito.","comoBancaPensa":"Explora a construção que a fala consagrou e a norma reprova."}},"PT-139":{"cognitivo":{"motivo":"Cobrar a concordância dessas palavras, de uso corrente em redação oficial.","palavraCritica":"concordar em gênero e número"},"comentario":{"resolucao":"CERTO. São adjetivos e variam: \"documento anexo\", \"certidões anexas\", \"cópia inclusa\". \"Obrigado\" segue a mesma lógica — uma mulher diz \"obrigada\". A forma invariável \"em anexo\" é locução adverbial e não varia, mas é a exceção, e não a regra. Item de aplicação direta em ofícios e memorandos.","fundamento":"Gramática normativa — concordância nominal de 'anexo', 'incluso' e 'obrigado'.","macete":"Anexo é adjetivo: varia. 'Em anexo' é locução: não varia.","erroComum":"Deixar 'anexo' invariável por analogia com 'em anexo'.","comoBancaPensa":"Item correto com aplicação imediata na rotina administrativa."}},"PT-140":{"cognitivo":{"motivo":"Cobrar a regra e detectar a incoerência entre o enunciado e o exemplo.","palavraCritica":"É proibida entrada"},"comentario":{"resolucao":"ERRADO. A regra enunciada está certa — sem determinante, o predicativo fica invariável —, mas o EXEMPLO a contraria: deveria ser \"É PROIBIDO entrada de pessoas não autorizadas\". Com artigo, haveria concordância: \"É proibida A entrada\". O item se autodesmente, e detectar isso é o que ele cobra.","fundamento":"Gramática normativa — concordância nominal em 'é proibido', 'é necessário', 'é bom'.","macete":"Sem artigo, invariável: é proibido entrada. Com artigo, concorda: é proibida a entrada.","erroComum":"Validar o item pela regra correta, sem conferir o exemplo.","comoBancaPensa":"Enuncia a regra corretamente e a ilustra com exemplo que a viola."}},"PT-141":{"cognitivo":{"motivo":"Cobrar a direção da relação hiperônimo/hipônimo.","palavraCritica":"hipônimo ... mais restrita"},"comentario":{"resolucao":"ERRADO. Está invertido nas duas pontas. \"Crime\" é HIPERÔNIMO — termo de sentido mais amplo, que engloba \"furto\". \"Furto\" é o hipônimo, de sentido mais específico. O prefixo entrega: hiper- é o que está acima, hipo- é o que está abaixo, como em hipertensão e hipotensão.","fundamento":"Semântica — relações de hiperonímia e hiponímia.","macete":"Hiper é maior e engloba. Hipo é menor e está contido.","erroComum":"Trocar os dois termos por não associar os prefixos.","comoBancaPensa":"Inverte a relação e ainda descreve erradamente a amplitude, dobrando o erro."}},"PT-142":{"cognitivo":{"motivo":"Cobrar o caráter contextual da sinonímia, princípio das questões de substituição.","palavraCritica":"qualquer contexto ... absoluta"},"comentario":{"resolucao":"ERRADO. A sinonímia perfeita praticamente não existe: os sinônimos diferem em registro, conotação, colocação e regência. \"Casa\" e \"lar\" são sinônimos, mas não se diz \"lar comercial\". Em prova, é exatamente aí que a banca opera — propõe substituição por sinônimo dicionarizado que, no contexto, altera o sentido, quebra a regência ou muda o registro.","fundamento":"Semântica — sinonímia e adequação contextual.","macete":"Sinônimo é aproximação, não igualdade. Sempre teste no contexto.","erroComum":"Aceitar substituição por confiar no dicionário, sem reler a frase.","comoBancaPensa":"Afirma como absoluta uma relação que é sempre contextual."}},"PT-143":{"cognitivo":{"motivo":"Contraexemplo: identificação correta da conotação, par que a banca inverte.","palavraCritica":"conotativo"},"comentario":{"resolucao":"CERTO. Conotação é o emprego figurado, em que a palavra se afasta do sentido literal. \"Abrir as portas\" significa aqui criar oportunidades, não movimentar uma porta. Denotação seria o sentido literal e dicionarizado. A distinção é cobrada em interpretação e também em itens de reescritura, porque a paráfrase precisa preservar o sentido figurado.","fundamento":"Semântica — denotação e conotação.","macete":"Denotação é o sentido do dicionário. Conotação é o figurado.","erroComum":"Trocar os dois termos por semelhança sonora.","comoBancaPensa":"Classifica corretamente um emprego figurado, num par que costuma permutar."}},"PT-144":{"cognitivo":{"motivo":"Cobrar a ambiguidade por possessivo de terceira pessoa e sua correção.","palavraCritica":"conforme o referente pretendido"},"comentario":{"resolucao":"CERTO. \"Seu\" pode remeter ao delegado ou ao escrivão, e nada no período resolve. O possessivo de terceira pessoa é ambíguo por natureza quando há dois referentes possíveis do mesmo gênero e número. A correção passa por explicitar: \"o prazo dele\", \"o próprio prazo\" ou reescrever nomeando o referente. É defeito de clareza, não erro gramatical — a frase está bem formada.","fundamento":"Semântica e redação oficial — ambiguidade por pronome possessivo.","macete":"Dois candidatos a dono e um 'seu' no meio: ambiguidade.","erroComum":"Não reconhecer ambiguidade em frase gramaticalmente correta.","comoBancaPensa":"Item correto que exige separar clareza de correção gramatical."}}});
